function ensureSmartTopDock(){
    // 2026-09-21：顶部 4 按钮（工作流/快捷图/日志/资产库）独立成组，固定在顶部居中显示，
    // 位置不随 AI 助手面板开合变化
    document.getElementById('smartTopDock')?.remove();
    let center = document.getElementById('smartTopCenter');
    if(!center){
        center = document.createElement('div');
        center.id = 'smartTopCenter';
        center.className = 'smart-top-center';
        document.body.appendChild(center);
    }
    const billingToggleBtn = document.getElementById('billingToggle');
    [smartWorkflowToggle, smartShortcutToggle, smartLogToggle, assetToggle, billingToggleBtn].forEach(el => {
        if(el && el.parentElement !== center) center.appendChild(el);
    });
}
ensureSmartTopDock();
function smartVisibleAgentRect(){
    if(!document.body.classList.contains('smart-agent-open') || !smartAgentPanel) return null;
    const rect = smartAgentPanel.getBoundingClientRect();
    if(rect.width < 40 || rect.height < 40) return null;
    return rect;
}
function smartUsableScreenBounds(pad=14){
    const agentRect = smartVisibleAgentRect();
    return {
        left:pad,
        top:pad,
        right:Math.max(pad, Math.min(window.innerWidth - pad, agentRect ? agentRect.left - pad : window.innerWidth - pad)),
        bottom:window.innerHeight - pad
    };
}
function positionFloatingPanelBelowButton(panel, button, options={}){
    if(!panel || !button) return;
    const bounds = smartUsableScreenBounds(options.pad || 14);
    const btn = button.getBoundingClientRect();
    const width = Math.min(options.width || panel.offsetWidth || 390, bounds.right - bounds.left);
    const maxHeight = Math.max(160, bounds.bottom - btn.bottom - 12);
    const left = Math.max(bounds.left, Math.min(bounds.right - width, btn.left + btn.width / 2 - width / 2));
    const top = Math.min(bounds.bottom - 120, btn.bottom + (options.gap || 10));
    panel.style.left = `${Math.round(left)}px`;
    panel.style.right = 'auto';
    panel.style.top = `${Math.round(top)}px`;
    panel.style.width = `${Math.round(width)}px`;
    panel.style.maxHeight = `${Math.round(Math.min(options.maxHeight || maxHeight, maxHeight))}px`;
    if(options.bottom === false) panel.style.bottom = 'auto';
}
