// 2026-10-06 端口拖拽兜底：浏览器原生拖放会接管手势并吞掉后续 mouseup，导致拖拽状态僵死、连线"断"住。
// 拖拽期间阻止原生 dragstart；pointercancel 时强制收尾清理。
window.addEventListener('dragstart', event => {
    if(portDragState) event.preventDefault();
}, true);
window.addEventListener('pointercancel', () => {
    if(!portDragState) return;
    portDragState = null;
    shell.classList.remove('port-dragging', 'batch-port-dragging');
    clearPortDragVisual();
    discardPendingUndo();
    render();
}, true);
