function restoreLocalEditMaskOverlay(){
    const rects = localEditRestoredRects.length ? localEditRestoredRects : (localEditRestoredRect ? [localEditRestoredRect] : []);
    if(!rects.length) return;
    const canvasEl = editDrawCanvas();
    if(!canvasEl?.width || !canvasEl?.height) return;
    const ctx = canvasEl.getContext('2d');
    if(!ctx) return;
    const lineWidth = Math.max(2, Math.min(canvasEl.width, canvasEl.height) / 260);
    ctx.save();
    ctx.globalCompositeOperation = 'source-over';
    ctx.fillStyle = 'rgba(255,45,85,0.46)';
    ctx.strokeStyle = 'rgba(56,189,248,0.96)';
    ctx.lineWidth = lineWidth;
    rects.forEach(rect => {
        const sw = Number(rect.sourceW) || canvasEl.width;
        const sh = Number(rect.sourceH) || canvasEl.height;
        const sx = canvasEl.width / Math.max(1, sw);
        const sy = canvasEl.height / Math.max(1, sh);
        const x = rect.x * sx;
        const y = rect.y * sy;
        const w = Math.max(1, rect.w * sx);
        const h = Math.max(1, rect.h * sy);
        if(w < 2 || h < 2) return;
        ctx.fillRect(x, y, w, h);
        ctx.strokeRect(x + lineWidth / 2, y + lineWidth / 2, Math.max(0, w - lineWidth), Math.max(0, h - lineWidth));
        localEditRects.push({x:Math.round(x), y:Math.round(y), w:Math.round(w), h:Math.round(h)});
    });
    ctx.restore();
    normalizeMaskPreviewCanvas(canvasEl);
    pushEditDrawHistory();
}
