function smartWorkflowSaveCategoryOptions(){
    // 2026-09-20 与首页工作流社区分类同步：内置社区分类（应用删除/改名记录）+ 我的工作流分类
    const prefs = presetWorkflowBuiltinCategoryPrefs();
    const hidden = new Set(prefs.hidden || []);
    const labels = prefs.labels || {};
    const names = [];
    WORKFLOW_NAV_CATEGORY_OPTIONS
        .filter(cat => !hidden.has(cat.value))
        .forEach(cat => {
            const label = String(labels[cat.value] || cat.label).trim();
            if(label) names.push(label);
        });
    workflowAssetCategories().forEach(cat => {
        const name = String(cat?.name || '').trim();
        if(name) names.push(name);
    });
    return Array.from(new Set(names));
}
