            const durationLabel = controlRoot?.querySelector?.('[data-video-duration]');
            const playButton = controlRoot?.querySelector?.('.smart-video-canvas-play');
            const range = controlRoot?.querySelector?.('.smart-video-canvas-range');
            const muteButton = controlRoot?.querySelector?.('.smart-video-canvas-mute');
            const duration = durationValue();
            const current = Number.isFinite(video.currentTime) && video.currentTime > 0 ? video.currentTime : 0;
            if(currentLabel) currentLabel.textContent = formatSmartVideoTime(current);
            if(durationLabel) durationLabel.textContent = formatSmartVideoTime(duration);
