function smartWavDuration(arrayBuffer){
    try{
        const view = new DataView(arrayBuffer);
        const readText = (offset, length) => {
            let text = '';
            for(let i = 0; i < length; i++) text += String.fromCharCode(view.getUint8(offset + i));
            return text;
        };
        if(view.byteLength < 44 || readText(0, 4) !== 'RIFF' || readText(8, 4) !== 'WAVE') return 0;
        let offset = 12;
        let sampleRate = 0;
        let blockAlign = 0;
        let dataBytes = 0;
        while(offset + 8 <= view.byteLength){
            const chunk = readText(offset, 4);
            const size = view.getUint32(offset + 4, true);
            const payload = offset + 8;
            if(chunk === 'fmt ' && size >= 16 && payload + 16 <= view.byteLength){
                sampleRate = view.getUint32(payload + 4, true);
                blockAlign = view.getUint16(payload + 12, true);
            }else if(chunk === 'data'){
                dataBytes = size;
                break;
            }
            offset = payload + size + (size % 2);
        }
        return sampleRate > 0 && blockAlign > 0 && dataBytes > 0 ? dataBytes / (sampleRate * blockAlign) : 0;
    }catch(e){
        return 0;
    }
}
function smartAudioWaveformHtml(seed=''){
    const text = String(seed || 'audio');
    let hash = 2166136261;
    for(let i = 0; i < text.length; i++){
        hash ^= text.charCodeAt(i);
        hash = Math.imul(hash, 16777619);
    }
    const bars = [];
    for(let i = 0; i < 48; i++){
        hash = Math.imul(hash ^ (i + 1), 16777619);
        const normalized = ((hash >>> 0) % 1000) / 1000;
        const envelope = 0.35 + 0.65 * Math.sin((i / 47) * Math.PI);
        const height = Math.round(18 + (normalized * 0.7 + envelope * 0.3) * 68);
        bars.push(`<span class="upload-preview-audio-wave-bar" style="--audio-bar-height:${height}%"></span>`);
    }
    return bars.join('');
}
