function presetWorkflowMeta(workflow){
    const name = workflow?.name || '';
    const title = workflow?.title || name.replace(/\.json$/i, '');
    const lower = `${name} ${title}`.toLowerCase();
    if(lower.includes('enhance') || title.includes('放大') || title.includes('增强')) return {tag:'影棚', icon:'sparkles', desc:'高清修复、细节增强、放大输出', tone:'green', cats:['recommended','photo','design','brand']};
    if(lower.includes('klein') || lower.includes('edit') || title.includes('融图') || title.includes('扩图')) return {tag:'设计', icon:'wand-sparkles', desc:'参考图改图、融合、扩图和局部重绘', tone:'blue', cats:['recommended','design','ecommerce','brand']};
    if(lower.includes('z-image') || lower.includes('zimage')) return {tag:'摄影', icon:'image-plus', desc:'从提示词生成首图或创意草案', tone:'cyan', cats:['recommended','photo','design','acg']};
    if(lower.includes('2511') || lower.includes('qwen')) return {tag:'电商', icon:'scan-eye', desc:'商品图编辑、结构保留和局部改写', tone:'violet', cats:['recommended','ecommerce','brand','design']};
    return {tag:'其他', icon:'workflow', desc:`${workflow?.field_count || 0} 个可调参数`, tone:'slate', cats:['other']};
}
function workflowDisplayTitle(workflow){
    const name = workflow?.name || '';
    const title = workflow?.title || name.replace(/\.json$/i, '');
    const map = {
        'Z-Image.json':'Z-Image 文生图',
        'custom/Z-Image.json':'Z-Image 文生图',
        'Z-Image-Enhance.json':'Z-Image 高清增强',
        'custom/Z-Image-Enhance.json':'Z-Image 高清增强',
        'Flux2-Klein.json':'Flux2 Klein 图像编辑',
        'custom/Flux2-Klein.json':'Flux2 Klein 图像编辑',
        '2511.json':'Qwen Image Edit 2511'
    };
    return map[name] || title || 'Comfy 工作流';
}
function presetWorkflowBuiltinCategoryPrefs(){
    // 与素材库 asset-manager.js 共用同一 localStorage key：社区分类跟随删除/改名
    try {
        const data = JSON.parse(localStorage.getItem('asset_manager_workflow_builtin_category_prefs_v1') || '{}');
        return data && typeof data === 'object' ? {
            hidden: Array.isArray(data.hidden) ? data.hidden.map(String) : [],
            labels: data.labels && typeof data.labels === 'object' ? data.labels : {}
        } : {hidden:[], labels:{}};
    } catch(_) {
        return {hidden:[], labels:{}};
    }
}

function presetWorkflowCategoryButtonsHtml(){
    if(presetWorkflowTab !== 'mine'){
        // 2026-09-20 社区分类与素材库工作流分组对应：应用删除/改名记录
        const prefs = presetWorkflowBuiltinCategoryPrefs();
        const hidden = new Set(prefs.hidden || []);
        const labels = prefs.labels || {};
        return [
            {value:'all', label:'全部'},
            ...WORKFLOW_NAV_CATEGORY_OPTIONS
                .filter(cat => !hidden.has(cat.value))
                .map(cat => ({value:cat.value, label:String(labels[cat.value] || cat.label)}))
        ].map(cat => `<button class="${presetWorkflowCategory === cat.value ? 'active' : ''}" type="button" data-preset-category="${escapeAttr(cat.value)}">${escapeHtml(cat.label)}</button>`).join('');
    }
    const cats = workflowAssetCategories();
    const values = new Set(['all', ...cats.map(cat => `wfcat:${cat.id || ''}`)]);
    if(!values.has(presetWorkflowCategory)) presetWorkflowCategory = 'all';
    const buttons = [
        `<button class="${presetWorkflowCategory === 'all' ? 'active' : ''}" type="button" data-preset-category="all">全部</button>`,
        ...cats.map(cat => {
            const value = `wfcat:${cat.id || ''}`;
            const count = (cat.items || []).filter(item => assetMediaKind(item) === 'workflow' || item.kind === 'workflow' || item.type === 'workflow').length;
            return `<button class="${presetWorkflowCategory === value ? 'active' : ''}" type="button" data-preset-category="${escapeAttr(value)}" title="分类：${escapeAttr(cat.name || '工作流')}">
                <span>${escapeHtml(cat.name || '工作流')}</span><small>${count}</small>
            </button>`;
        }).filter(Boolean)
    ];
    buttons.push(`<span class="preset-workflow-cat-tools">
        <button type="button" data-preset-category-action="new" title="新建工作流分类"><i data-lucide="plus"></i><span>新建</span></button>
        <button type="button" data-preset-category-action="rename" ${presetWorkflowCategory === 'all' ? 'disabled' : ''} title="重命名当前分类"><i data-lucide="pencil"></i><span>重命名</span></button>
    </span>`);
    return buttons.join('');
}
