function markWorkflowGroupSource(group, item={}){
    if(!isWorkflowGroupNode(group)) return;
    const assetId = String(item.id || item.assetId || item.workflowAssetId || '').trim();
    if(assetId){
        group.workflowAssetId = assetId;
        group.sourceWorkflowAssetId = assetId;
        group.source_workflow_id = assetId;
    }
    if(item.name) group.source_workflow_name = item.name;
    if(item.url) group.source_workflow_url = item.url;
}
function syncCanvasSourceWorkflowToGroup(){
    if(!canvas?.source_workflow_id) return false;
    const groups = nodes.filter(isWorkflowGroupNode);
    if(groups.length !== 1 || workflowAssetIdForGroup(groups[0])) return false;
    markWorkflowGroupSource(groups[0], {
        id:canvas.source_workflow_id,
        name:canvas.source_workflow_name || '',
        url:canvas.source_workflow_url || ''
    });
    return true;
}
