    return savedWorkflowPanelItems().find(item => String(item?.name || '').trim().toLowerCase() === key)
        || workflowAssetCategories().flatMap(cat => cat.items || []).find(item => String(item?.name || '').trim().toLowerCase() === key)
        || null;
