    const fixed = smartNodeFixedEngine(node);
    const engine = s.engine || fixed;
    if(isApiLikeEngine(engine) && s.apiKind === 'video') return '视频生成';
    if(isApiLikeEngine(engine) && s.apiKind === 'audio') return '音频生成';
