    comfyQuickStatus.classList.toggle('checking', next === 'checking');
    comfyQuickStatus.classList.toggle('offline', next === 'offline');
    comfyQuickStatus.setAttribute('aria-label', label || (next === 'online' ? 'ComfyUI 已连接' : next === 'checking' ? 'ComfyUI 检测中' : 'ComfyUI 未连接')); 
