const SMART_VERSION_STORAGE_KEY = 'smartCanvas.loadedVersion';
function smartVersionClean(value=''){
    const raw = String(value || '').trim().replace(/^version\s*[:：-]?\s*/i, '');
    if(!raw || /[<>{}\s]/.test(raw)) return '';
    return raw.slice(0, 32);
}
function smartVersionReadStored(){
    try {
        return smartVersionClean(localStorage.getItem(SMART_VERSION_STORAGE_KEY) || '');
    } catch(_) {
        return '';
    }
}
function smartVersionRemember(version=''){
    const clean = smartVersionClean(version);
    if(!clean) return;
    try {
        localStorage.setItem(SMART_VERSION_STORAGE_KEY, clean);
    } catch(_) {}
}
function smartVersionInitialLoaded(){
    return smartVersionReadStored() || '';
}
const smartVersionState = {
    loaded:smartVersionInitialLoaded(),
    current:'',
    server:'',
    latest:'',
    source:'lan',
    notes:[],
    updateAvailable:false,
    checking:false,
    updating:false,
    lastCheckAt:0
};
function smartVersionLabel(value='', mode='full'){
    const clean = smartVersionClean(value);
    if(!clean) return 'V-';
    if(/^v/i.test(clean)){
        // 2026-10-15 新命名 V<年2位>.<月>.<日>.<当日序号>：compact 去年份段 → V10.14.1
        if(mode === 'compact'){
            const m = clean.match(/^v\d{1,2}\.(\d{1,2})\.(\d{1,2})\.(\d+)$/i);
            if(m) return `V${m[1].padStart(2,'0')}.${m[2].padStart(2,'0')}.${m[3]}`;
        }
        return clean.toUpperCase();
    }
    return `V${clean}`;
}
function smartVersionParts(value=''){
    return smartVersionClean(value).match(/\d+/g)?.map(Number) || [];
}
function smartVersionGreater(a='', b=''){
    const left = smartVersionParts(a);
    const right = smartVersionParts(b);
    const len = Math.max(left.length, right.length);
    for(let i = 0; i < len; i += 1){
        const av = left[i] || 0;
        const bv = right[i] || 0;
        if(av !== bv) return av > bv;
    }
    return false;
}
function setSmartUpdateSummary(kind='warn', title='', text=''){
    const box = document.getElementById('smartUpdateSummary');
    const titleEl = document.getElementById('smartUpdateSummaryTitle');
    const textEl = document.getElementById('smartUpdateSummaryText');
    if(box){
        box.classList.remove('ok', 'warn', 'fail');
        box.classList.add(kind || 'warn');
    }
    if(titleEl) titleEl.textContent = title || '版本状态';
    if(textEl) textEl.textContent = text || '';
}
