        const spreadsheetClass = isSpreadsheetMediaItem(ref) ? ' is-spreadsheet' : '';
        return `<span class="smart-agent-file-thumb${spreadsheetClass}" data-file-kind="${escapeAttr(smartFileLabel(ref).toLowerCase())}">${smartFileIconHtml(ref)}<small>${escapeHtml(smartFileLabel(ref))}</small></span>`;
