function smartAgentImageRunSettings(){
    const runSettings = cloneSmartSettings(settings);
    if(isApiLikeEngine(runSettings.engine) && runSettings.apiKind === 'video'){
        runSettings.apiKind = 'image';
    }
    const imageProvider = smartAgentImageProvider();
    const providerModels = providerImageModels(imageProvider);
    let imageModel = smartAgentImageModel(imageProvider);
    const hasAgentRefs = smartAgentAttachedRefs.some(ref => ref?.kind === 'image' && ref?.url);
    const refPreferredModel = providerModels.find(model => /banana/i.test(model)) || providerModels[0] || '';
    if(hasAgentRefs && refPreferredModel) imageModel = refPreferredModel;
    if(imageModel && !providerModels.includes(imageModel)) imageModel = refPreferredModel || providerModels[0] || '';
    if(imageProvider && imageModel){
        runSettings.engine = 'api';
        runSettings.apiKind = 'image';
        runSettings.provider_id = imageProvider;
        runSettings.model = imageModel;
    }
    return applySmartAgentSizeChoiceToRunSettings(runSettings);
}
