function saveSmartAgentHistory(){
    const messages = smartAgentMessagesState.filter(msg => !msg.pending && String(msg?.content || '').trim());
    if(!messages.length) return;
    const id = smartAgentConversationId || `local-${Date.now()}`;
    if(!smartAgentConversationId) smartAgentConversationId = id;
    const now = Date.now();
    const record = {
        id,
        conversationId:smartAgentConversationId,
        title:smartAgentConversationTitle(messages),
        summary:smartAgentConversationSummary(messages),
        updatedAt:now,
        messages:messages.slice(-40)
    };
    const next = [record, ...loadSmartAgentHistory().filter(item => item.id !== id)].slice(0, 24);
    localStorage.setItem(SMART_AGENT_HISTORY_KEY, JSON.stringify(next));
    renderSmartAgentHistory();
}
