function smartAgentInlineMarkdown(text){
    return escapeHtml(text)
        .replace(/`([^`]+)`/g, '<code>$1</code>')
        .replace(/\*\*([^*\n]+)\*\*/g, '<strong>$1</strong>')
        .replace(/(^|[^*])\*([^*\n]+)\*/g, '$1<em>$2</em>');
}
function renderSmartAgentMarkdown(content){
    const lines = String(content || '').replace(/\r\n?/g, '\n').split('\n');
    let html = '';
    let paragraph = [];
    let listType = '';
    let codeLines = [];
    let inCode = false;
    const flushParagraph = () => {
        if(!paragraph.length) return;
        html += `<p>${paragraph.map(smartAgentInlineMarkdown).join('<br>')}</p>`;
        paragraph = [];
    };
    const closeList = () => {
        if(!listType) return;
        html += `</${listType}>`;
        listType = '';
    };
    lines.forEach(line => {
        if(/^\s*```/.test(line)){
            if(inCode){
                html += `<pre><code>${escapeHtml(codeLines.join('\n'))}</code></pre>`;
                codeLines = [];
                inCode = false;
            } else {
                flushParagraph();
                closeList();
                inCode = true;
            }
            return;
        }
        if(inCode){
            codeLines.push(line);
            return;
        }
        if(!line.trim()){
            flushParagraph();
            closeList();
            return;
        }
        const heading = line.match(/^\s{0,3}(#{1,3})\s+(.+)$/);
        if(heading){
            flushParagraph();
            closeList();
            const level = Math.min(3, heading[1].length);
            html += `<h${level}>${smartAgentInlineMarkdown(heading[2].trim())}</h${level}>`;
            return;
        }
        const unordered = line.match(/^\s*[-*]\s+(.+)$/);
        const ordered = line.match(/^\s*\d+[.)]\s+(.+)$/);
        if(unordered || ordered){
            flushParagraph();
            const nextType = ordered ? 'ol' : 'ul';
            if(listType && listType !== nextType) closeList();
            if(!listType){
                listType = nextType;
                html += `<${listType}>`;
            }
            html += `<li>${smartAgentInlineMarkdown((unordered || ordered)[1].trim())}</li>`;
            return;
        }
        closeList();
        paragraph.push(line.trim());
    });
    if(inCode) html += `<pre><code>${escapeHtml(codeLines.join('\n'))}</code></pre>`;
    flushParagraph();
    closeList();
    return html || '<p></p>';
}
