function smartAgentNormalizeOutputs(rawOutputs=[], namePrefix='agent-output'){
    return resultMediaUrls(rawOutputs).map((item, index) => {
        const source = typeof item === 'string' ? {url:item} : (item || {});
        const url = source.url || source.path || source.src || source.uri || '';
        if(!url) return null;
        const kind = source.kind || source.type || source.mediaKind || 'image';
        return copyMediaSizeFields(source, {
            url,
            name:source.name || source.filename || `${namePrefix}-${index + 1}.png`,
            kind:kind || 'image'
        });
    }).filter(item => item?.url && (item.kind || 'image') === 'image');
}
