function gcdInt(a, b){
    a = Math.abs(Math.round(Number(a) || 0));
    b = Math.abs(Math.round(Number(b) || 0));
    while(b){ const t = b; b = a % b; a = t; }
    return a || 1;
}
function imageSizeForRatio(img){
    const w = Math.round(Number(img?.natural_w || img?.width || img?.w || img?.layout_w || img?.preview_w || 0));
    const h = Math.round(Number(img?.natural_h || img?.height || img?.h || img?.layout_h || img?.preview_h || 0));
    return w > 0 && h > 0 ? {w, h} : null;
}
// 根据当前输出尺寸生成比例标签。只有接近标准比例时才显示标准值，
// 自定义比例则保留实际比例，避免所有横图都被误标成 3:2。
function ratioTextFromDimensions(width, height){
    const rawW = Math.round(Number(width) || 0);
    const rawH = Math.round(Number(height) || 0);
    if(!(rawW > 0 && rawH > 0)) return '';
    const w = rawW;
    const h = rawH;
    const target = w / h;
    const standards = [
        ['1:1', 1], ['2:3', 2 / 3], ['3:2', 3 / 2], ['3:4', 3 / 4],
        ['4:3', 4 / 3], ['4:5', 4 / 5], ['5:4', 5 / 4],
        ['9:16', 9 / 16], ['16:9', 16 / 9], ['21:9', 21 / 9], ['9:21', 9 / 21]
    ];
    let nearest = standards[0];
    let error = Infinity;
    standards.forEach(item => {
        const nextError = Math.abs(target - item[1]) / Math.max(target, item[1]);
        if(nextError < error){
            error = nextError;
            nearest = item;
        }
    });
    // 3% 以内视为模型输出的标准比例（像素尺寸常会因 16 的倍数取整而略有误差）。
    if(error <= 0.03) return nearest[0];
    const g = gcdInt(w, h);
    const rw = Math.round(w / g);
    const rh = Math.round(h / g);
    if(rw <= 32 && rh <= 32) return `${rw}:${rh}`;
    if(target >= 1) return `${target.toFixed(2)}:1`;
    return `1:${(1 / target).toFixed(2)}`;
}
