    const configured = String(assetLibrary.active_library_id || '').trim();
    const configuredSource = sources.find(source => source.id === configured);
    if(configuredSource && assetSourceHasMedia(configuredSource)) return configuredSource.id;
    const firstPopulated = sources.find(assetSourceHasMedia);
