    const branchGroup = (nodes || []).find(n => n && n.type === 'smart-group' && n.multiBranchSourceId === node.id);
    if(!branchGroup) return false;
    const groupUrls = new Set((branchGroup.images || []).map(i => i && i.url).filter(Boolean));
    if(!groupUrls.size) return false;
    const logUrls = outputItems.map(item => (typeof item === 'string' ? item : item && item.url)).filter(Boolean);
