    if(!additions.length) return false;
    const meta = logMetaForRecoveredNode(log, node);
    const appended = Boolean(node.appendPendingOutput) && smartNodeHasDisplayResult(node)
        ? appendOutputsToNode(node, additions, kind, {meta, limit:SMART_APPEND_OUTPUT_MAX, skipShift:true, baseBox})
        : replaceOutputsToNodeWithHistory(node, additions, kind, meta, {skipShift:true, preserveHistory:false});
    if(!appended.length && !smartNodeHasDisplayResult(node)) return false;
    markSmartNodeComplete(node, meta);
    node.outputKind = kind;
