function createSmartImageGroupAt(point, images=[], options={}){
    const normalized = (images || []).filter(item => item?.url).map(item => ({
        ...item,
        kind:item.kind || mediaKindForItem(item)
    }));
    if(normalized.length < 2) return null;
    const center = point || viewportCenter();
    const group = createSmartGroupNode(
        Math.round((center.x || 0) - SMART_GROUP_DEFAULT_WIDTH / 2),
        Math.round((center.y || 0) - SMART_GROUP_DEFAULT_HEIGHT / 2),
        {skipUndo:true, skipRender:true, skipSave:true, select:false}
    );
    group.title = options.title || '智能分组';
    group.images = normalized;
    group.items = [];
    group.scale = MEDIA_GROUP_DEFAULT_SCALE;
    // 让智能分组按当前图片数量自动计算网格和高度，而不是保留空组的默认尺寸。
    delete group.w;
    delete group.h;
    markSmartNodeImagesEdited(group);
    const layout = smartGroupThumbLayout(group);
    if(layout?.width && layout?.height){
        group.w = Math.max(SMART_GROUP_MIN_WIDTH, Math.round(layout.width));
        group.h = Math.max(SMART_GROUP_MIN_HEIGHT, Math.round(layout.height));
        group.x = Math.round((center.x || 0) - group.w / 2);
        group.y = Math.round((center.y || 0) - group.h / 2);
    }
    return group;
}
function createWorkflowGroupFromSelection(){
    const ids = selectedNodeIds();
    const selected = ids.map(id => nodes.find(n => n.id === id)).filter(node => node && !isWorkflowGroupNode(node));
    if(!selected.length){ toast('请先选中要创建工作流组的节点'); return null; }
    pushUndo();
    const rects = selected.map(nodeRect);
    const minX = Math.min(...rects.map(r => r.x));
    const minY = Math.min(...rects.map(r => r.y));
    const maxX = Math.max(...rects.map(r => r.x + r.width));
    const maxY = Math.max(...rects.map(r => r.y + r.height));
    const padX = 56;
    const padTop = 68;
    const padBottom = 48;
    const node = {
        id:uid('wfgroup'),
        type:'workflow-group',
        x:Math.round(minX - padX),
        y:Math.round(minY - padTop),
        w:Math.max(WORKFLOW_GROUP_MIN_WIDTH, Math.round(maxX - minX + padX * 2)),
        h:Math.max(WORKFLOW_GROUP_MIN_HEIGHT, Math.round(maxY - minY + padTop + padBottom)),
        title:'新建分组',
        items:selected.map(item => item.id),
        created_at:Date.now()
    };
    nodes.push(node);
    selectedIds = [];
    selectedId = node.id;
    selectedImage = {nodeId:'', index:-1};
    render();
    scheduleSave();
    return node;
}
const SMART_FRAME_OPACITY_KEY = 'smart_canvas_frame_opacity';
const SMART_FRAME_OPACITY_DEFAULT = 0.56;
const SMART_FRAME_OPACITY_MIN = 0;
const SMART_FRAME_OPACITY_MAX = 0.85;
function normalizeSmartFrameOpacity(value){
    if(value === null || value === undefined || value === '') return SMART_FRAME_OPACITY_DEFAULT;
    const next = Number(value);
    if(!Number.isFinite(next)) return SMART_FRAME_OPACITY_DEFAULT;
    return Math.round(Math.max(SMART_FRAME_OPACITY_MIN, Math.min(SMART_FRAME_OPACITY_MAX, next)) * 100) / 100;
}
function loadSmartFrameOpacity(){
    try {
        const stored = localStorage.getItem(SMART_FRAME_OPACITY_KEY);
        return stored === null ? SMART_FRAME_OPACITY_DEFAULT : normalizeSmartFrameOpacity(stored);
    } catch(e){
        return SMART_FRAME_OPACITY_DEFAULT;
    }
}
let smartFrameOpacity = loadSmartFrameOpacity();
function smartFrameOpacityLabel(value=smartFrameOpacity){
    return `${Math.round(normalizeSmartFrameOpacity(value) * 100)}%`;
}
function frameColorWithOpacity(color, opacity=smartFrameOpacity){
    const match = String(color || '').match(/^rgba?\(\s*([\d.]+)\s*,\s*([\d.]+)\s*,\s*([\d.]+)(?:\s*,\s*[\d.]+)?\s*\)$/i);
    if(!match) return color;
    const alpha = String(normalizeSmartFrameOpacity(opacity)).replace(/^0\./, '.');
    return `rgba(${match[1]},${match[2]},${match[3]},${alpha})`;
}
function updateSmartFrameOpacityControls(){
    document.querySelectorAll('[data-smart-frame-opacity]').forEach(input => {
        input.value = String(smartFrameOpacity);
    });
    document.querySelectorAll('[data-smart-frame-opacity-value]').forEach(el => {
        el.textContent = smartFrameOpacityLabel();
    });
}
function setSmartFrameOpacity(value, options={}){
    const next = normalizeSmartFrameOpacity(value);
    if(next === smartFrameOpacity && !options.force) return;
    smartFrameOpacity = next;
    document.documentElement.style.setProperty('--smart-frame-opacity', String(next));
    try { localStorage.setItem(SMART_FRAME_OPACITY_KEY, String(next)); } catch(e) {}
    updateSmartFrameOpacityControls();
    if(options.render !== false) render();
}
setSmartFrameOpacity(smartFrameOpacity, {render:false, force:true});
