async function fetchImageBlobForClipboard(item){
    const url = smartOriginalMediaUrl(item);
    if(!url) throw new Error('图片不存在');
    const name = downloadNameForMediaItem(item, 'image');
    const direct = /^data:|^blob:/i.test(url);
    const requestUrl = direct ? url : `/api/download-output?url=${encodeURIComponent(url)}&name=${encodeURIComponent(name)}`;
    const response = await fetch(requestUrl);
    if(!response.ok) throw new Error('读取图片失败');
    return response.blob();
}
async function imageBlobToPngBlob(blob){
    if(!blob) throw new Error('图片读取失败');
    const bitmap = await createImageBitmap(blob);
    const canvasEl = document.createElement('canvas');
    canvasEl.width = bitmap.width;
    canvasEl.height = bitmap.height;
    const ctx = canvasEl.getContext('2d');
    ctx.drawImage(bitmap, 0, 0);
    bitmap.close?.();
    return await new Promise((resolve, reject) => {
        canvasEl.toBlob(out => out ? resolve(out) : reject(new Error('图片转换失败')), 'image/png');
    });
}
async function smartAgentImageSizeForRef(ref){
    const existing = imageSizeForRatio(ref);
    if(existing) return existing;
    if(!ref?.url) return null;
    const blob = await fetchImageBlobForClipboard(ref);
    const bitmap = await createImageBitmap(blob);
    const size = {w:bitmap.width || 0, h:bitmap.height || 0};
    bitmap.close?.();
    return size.w > 0 && size.h > 0 ? size : null;
}
async function smartAgentPadBlobToRatio(blob, ratioKey, options={}){
    if(!blob) throw new Error('图片读取失败');
    const bitmap = await createImageBitmap(blob);
    const ratioMap = {square:1, portrait:2/3, landscape:3/2, portrait43:3/4, landscape43:4/3, story:9/16, wide:16/9, ultratall:9/21, ultrawide:21/9};
    const targetRatio = ratioMap[ratioKey] || 1;
    const sourceW = Math.max(1, bitmap.width || 1);
    const sourceH = Math.max(1, bitmap.height || 1);
    const targetW = Math.max(1, Math.round(Number(options?.targetSize?.w) || 0));
    const targetH = Math.max(1, Math.round(Number(options?.targetSize?.h) || 0));
    const canvasW = targetW > 0 && targetH > 0 ? targetW : (sourceW / sourceH > targetRatio ? sourceW : Math.max(1, Math.round(sourceH * targetRatio)));
    const canvasH = targetW > 0 && targetH > 0 ? targetH : (sourceW / sourceH > targetRatio ? Math.max(1, Math.round(sourceW / targetRatio)) : sourceH);
    const canvasEl = document.createElement('canvas');
    canvasEl.width = canvasW;
    canvasEl.height = canvasH;
    const ctx = canvasEl.getContext('2d');
    ctx.fillStyle = options.fillStyle || '#111111';
    ctx.fillRect(0, 0, canvasW, canvasH);
    try {
        const coverScale = Math.max(canvasW / sourceW, canvasH / sourceH);
        const coverW = Math.max(1, Math.round(sourceW * coverScale));
        const coverH = Math.max(1, Math.round(sourceH * coverScale));
        const coverX = Math.round((canvasW - coverW) / 2);
        const coverY = Math.round((canvasH - coverH) / 2);
        ctx.save();
        ctx.filter = `blur(${options.blur || 36}px)`;
        ctx.drawImage(bitmap, coverX, coverY, coverW, coverH);
        ctx.restore();
    } catch(_) {}
    const fitScale = Math.min(canvasW / sourceW, canvasH / sourceH);
    const drawW = Math.max(1, Math.round(sourceW * fitScale));
    const drawH = Math.max(1, Math.round(sourceH * fitScale));
    const drawX = Math.round((canvasW - drawW) / 2);
    const drawY = Math.round((canvasH - drawH) / 2);
    ctx.drawImage(bitmap, drawX, drawY, drawW, drawH);
    bitmap.close?.();
    return await new Promise((resolve, reject) => {
        canvasEl.toBlob(out => out ? resolve(out) : reject(new Error('图片转换失败')), 'image/png');
    });
}
async function smartAgentCropBlobToSize(blob, targetSize){
    if(!blob || !targetSize?.w || !targetSize?.h) return blob;
    const bitmap = await createImageBitmap(blob);
    const sourceW = Math.max(1, bitmap.width || 1);
    const sourceH = Math.max(1, bitmap.height || 1);
    const targetRatio = Number(targetSize.w) / Number(targetSize.h);
    let cropW = sourceW;
    let cropH = sourceH;
    if(sourceW / sourceH > targetRatio){
        cropW = Math.max(1, Math.round(sourceH * targetRatio));
    } else {
        cropH = Math.max(1, Math.round(sourceW / targetRatio));
    }
    cropW = Math.min(sourceW, cropW);
    cropH = Math.min(sourceH, cropH);
    const cropX = Math.max(0, Math.round((sourceW - cropW) / 2));
    const cropY = Math.max(0, Math.round((sourceH - cropH) / 2));
    const canvasEl = document.createElement('canvas');
    canvasEl.width = cropW;
    canvasEl.height = cropH;
    const ctx = canvasEl.getContext('2d');
    ctx.drawImage(bitmap, cropX, cropY, cropW, cropH, 0, 0, cropW, cropH);
    bitmap.close?.();
    return await new Promise((resolve, reject) => {
        canvasEl.toBlob(out => out ? resolve(out) : reject(new Error('图片转换失败')), 'image/png');
    });
}
async function smartResizeBlobToShortestEdge(blob, shortEdge){
    const target = Math.max(16, Math.min(8192, Math.round(Number(shortEdge) || 0)));
    if(!blob || !target) return null;
    const bitmap = await createImageBitmap(blob);
    const sourceW = Math.max(1, bitmap.width || 1);
    const sourceH = Math.max(1, bitmap.height || 1);
    const shortest = Math.max(1, Math.min(sourceW, sourceH));
    const scale = target / shortest;
    const width = Math.max(1, Math.round(sourceW * scale));
    const height = Math.max(1, Math.round(sourceH * scale));
    const canvasEl = document.createElement('canvas');
    canvasEl.width = width;
    canvasEl.height = height;
    const ctx = canvasEl.getContext('2d');
    ctx.drawImage(bitmap, 0, 0, width, height);
    bitmap.close?.();
    const outBlob = await new Promise((resolve, reject) => {
        canvasEl.toBlob(out => out ? resolve(out) : reject(new Error('图片转换失败')), 'image/png');
    });
    return {blob:outBlob, width, height, sourceW, sourceH, target};
}
async function smartAgentPrepareFixedRatioRefs(requestRefs=[], runSettings=settings){
    const originalRefs = (requestRefs || []).filter(ref => ref?.url);
    const imageRefs = imageRefsOnly(originalRefs);
    if(!imageRefs.length || !smartAgentIsFixedStandardRatioModel(runSettings)) return {refs:originalRefs, runSettings, preserveRatio:false, sourceSize:null};
    const ratioSettingKey = runSettings.engine === 'modelscope' ? 'msRatio' : 'ratio';
    const customRatioKey = runSettings.engine === 'modelscope' ? 'msCustomRatio' : 'customRatio';
    const customSizeKey = runSettings.engine === 'modelscope' ? 'msCustomSize' : 'customSize';
    const currentRatio = String(runSettings[ratioSettingKey] || '').trim();
    if(runSettings[customRatioKey] || runSettings[customSizeKey] || (currentRatio && currentRatio !== 'square')){
        return {refs:originalRefs, runSettings, preserveRatio:false, sourceSize:null};
    }
    // 循环/并发场景里，第一张图经常只是占位或上游首图，不应成为整组比例模板。
    // 这里改为优先取最后一张有尺寸信息的图，让当前轮/当前输出的比例生效。
    let sourceRef = null;
    let sourceSize = null;
    for(let i = imageRefs.length - 1; i >= 0; i--){
        const size = await smartAgentImageSizeForRef(imageRefs[i]);
        if(size){
            sourceRef = imageRefs[i];
            sourceSize = size;
            break;
        }
    }
    if(!sourceSize) return {refs:originalRefs, runSettings, preserveRatio:false, sourceSize:null};
    const preparedSettings = cloneSmartSettings(runSettings || settings);
    const exactRatioKey = smartAgentRatioKeyFromSize(sourceSize);
    const ratioKey = smartAgentCanonicalStandardRatioKeyFromSize(sourceSize);
    if(preparedSettings.engine === 'modelscope'){
        preparedSettings.msRatio = ratioKey;
        preparedSettings.msCustomRatio = '';
    } else if(isApiLikeEngine(preparedSettings.engine)){
        preparedSettings.ratio = ratioKey;
        preparedSettings.customRatio = '';
    }
    const customSizeMatchesRatio = (() => {
        const parsed = parseSizeValue(preparedSettings.engine === 'modelscope' ? preparedSettings.msCustomSize : preparedSettings.customSize);
        if(!parsed?.width || !parsed?.height) return false;
        return smartAgentRatioKeyFromSize(`${parsed.width}x${parsed.height}`) === ratioKey;
    })();
    if(!exactRatioKey){
        if(preparedSettings.engine === 'modelscope'){
            if(preparedSettings.msResolution === 'custom') preparedSettings.msResolution = '1k';
            preparedSettings.msCustomSize = '';
        } else if(isApiLikeEngine(preparedSettings.engine)){
            if(preparedSettings.resolution === 'custom') preparedSettings.resolution = '1k';
            preparedSettings.customSize = '';
        }
    } else if(!customSizeMatchesRatio){
        if(preparedSettings.engine === 'modelscope'){
            if(preparedSettings.msResolution === 'custom') preparedSettings.msResolution = '1k';
            preparedSettings.msCustomSize = '';
        } else if(isApiLikeEngine(preparedSettings.engine)){
            if(preparedSettings.resolution === 'custom') preparedSettings.resolution = '1k';
            preparedSettings.customSize = '';
        }
    }
    const targetSizeText = smartAgentImageSizeForRun(preparedSettings);
    const targetSize = parseSizeValue(targetSizeText);
    const preparedImages = [];
    for(const ref of imageRefs){
        const blob = await fetchImageBlobForClipboard(ref);
        const padded = await smartAgentPadBlobToRatio(blob, ratioKey, {targetSize, fillStyle:'#111111'});
        const base = (ref.name || smartImageNameFromUrl(ref.url) || 'image').replace(/\.[^.]+$/, '');
        const file = await uploadCroppedBlob(padded, `${base}_pad_${ratioKey}.png`);
        preparedImages.push({
            ...ref,
            url:file?.url || ref.url,
            name:file?.name || `${base}_pad_${ratioKey}.png`,
            paddedForRatio:ratioKey,
            sourceSize:`${sourceSize.w}x${sourceSize.h}`,
            sourceRatioKey:ratioKey
        });
    }
    const preparedByKey = new Map(preparedImages.map(ref => [smartAgentRefKey(ref), ref]));
    const refs = originalRefs.map(ref => {
        if(!ref?.url || mediaKindForItem(ref) !== 'image') return ref;
        return preparedByKey.get(smartAgentRefKey(ref)) || ref;
    });
    return {refs, runSettings:preparedSettings, preserveRatio:true, sourceSize, ratioKey, originalRefs};
}
async function smartAgentCropOutputsToSourceRatio(outputs=[], sourceSize=null){
    if(!sourceSize?.w || !sourceSize?.h) return outputs || [];
    const list = smartAgentNormalizeOutputs(outputs, 'agent-output');
    const cropped = [];
    for(const output of list){
        if(!output?.url){
            cropped.push(output);
            continue;
        }
        try {
            const blob = await fetchImageBlobForClipboard(output);
            const croppedBlob = await smartAgentCropBlobToSize(blob, sourceSize);
            const base = (output.name || smartImageNameFromUrl(output.url) || 'agent-output').replace(/\.[^.]+$/, '');
            const file = await uploadCroppedBlob(croppedBlob, `${base}_ratio.png`);
            cropped.push(copyMediaSizeFields(output, {
                url:file?.url || output.url,
                name:file?.name || `${base}_ratio.png`,
                kind:'image'
            }));
        } catch(_) {
            cropped.push(output);
        }
    }
    return cropped;
}
async function copyImageItemToClipboard(item){
    const blob = await fetchImageBlobForClipboard(item);
    const png = await imageBlobToPngBlob(blob);
    // 2026-10-06 修复：非安全上下文（如用局域网 IP 访问）下 navigator.clipboard 不可用，
    // 走 execCommand 降级；仍失败才报错。
    if(navigator.clipboard?.write && typeof ClipboardItem !== 'undefined' && window.isSecureContext){
        await navigator.clipboard.write([new ClipboardItem({'image/png':png})]);
        return;
    }
    const ok = await legacyCopyImageBlobViaDom(png);
    if(!ok) throw new Error('当前浏览器不支持复制图片（请用 localhost/HTTPS 访问）');
}
function legacyCopyImageBlobViaDom(pngBlob){
    return new Promise(resolve => {
        let settled = false;
        const finish = ok => {
            if(settled) return;
            settled = true;
            try{ window.getSelection()?.removeAllRanges(); }catch(_){}
            try{ container?.remove(); }catch(_){}
            try{ URL.revokeObjectURL(url); }catch(_){}
            document.removeEventListener('copy', onCopy, true);
            resolve(ok);
        };
        let url = '';
        let container = null;
        const onCopy = event => {
            try{
                event.clipboardData?.setData('image/png', pngBlob);
                event.preventDefault();
                finish(true);
            }catch(_){ finish(false); }
        };
        try{
            url = URL.createObjectURL(pngBlob);
            container = document.createElement('div');
            container.contentEditable = 'true';
            container.style.cssText = 'position:fixed;left:-9999px;top:0;width:10px;height:10px;opacity:0;';
            const img = document.createElement('img');
            img.src = url;
            container.appendChild(img);
            document.body.appendChild(container);
            const range = document.createRange();
            range.selectNode(img);
            const selection = window.getSelection();
            selection?.removeAllRanges();
            selection?.addRange(range);
            document.addEventListener('copy', onCopy, true);
            if(!document.execCommand('copy')) setTimeout(() => finish(false), 120);
            setTimeout(() => finish(false), 1500);
        }catch(_){ finish(false); }
    });
}
function ensureSmartImageContextMenu(){
    if(smartImageContextMenu) return smartImageContextMenu;
    const menu = document.createElement('div');
    menu.className = 'smart-image-context-menu';
    menu.innerHTML = `
        <button type="button" data-smart-image-context-action="copy"><span>复制到剪贴板</span></button>
        <button type="button" data-smart-image-context-action="asset"><span>创建资产</span></button>
    `;
    menu.addEventListener('mousedown', event => event.stopPropagation());
    menu.addEventListener('contextmenu', event => {
        event.preventDefault();
        event.stopPropagation();
    });
    menu.addEventListener('click', async event => {
        const btn = event.target.closest('[data-smart-image-context-action]');
        if(!btn || !smartImageContextTarget?.item?.url) return;
        event.preventDefault();
        event.stopPropagation();
        const action = btn.dataset.smartImageContextAction || '';
        const target = smartImageContextTarget;
        closeSmartImageContextMenu();
        try {
            if(action === 'copy'){
                await copyImageItemToClipboard(target.item);
                toast('已复制图片到剪贴板');
            } else if(action === 'asset'){
                // 2026-10-06 即时反馈：保存含 AI 分类，可能需要数秒，先给提示
                toast('正在保存到资产库…');
                await addUrlToAssetLibrary(target.item.url, target.item.name || smartImageNameFromUrl(target.item.url));
            }
        } catch(err) {
            toast((err.message || '操作失败').slice(0, 160));
        }
    });
    document.body.appendChild(menu);
    smartImageContextMenu = menu;
    return menu;
}
function closeSmartImageContextMenu(){
    smartImageContextTarget = null;
    smartImageContextMenu?.classList.remove('open');
}
function openSmartImageContextMenu(event, target){
    const item = imageForDisplay(target?.image || {});
    if(!item?.url || mediaKindForItem(item) !== 'image') return false;
    event.preventDefault();
    event.stopPropagation();
    event.stopImmediatePropagation?.();
    clearImageClickTimer();
    suppressImageClickUntil = Date.now() + 260;
    selectedId = target.owner?.id || target.nodeId || selectedId;
    selectedIds = [];
    selectedImage = {nodeId:target.targetNodeId || target.owner?.id || '', index:Number(target.imageIndex) || 0};
    syncSelectionUi();
    smartImageContextTarget = {...target, item};
    const menu = ensureSmartImageContextMenu();
    const w = 188;
    const h = 104;
    const left = Math.max(8, Math.min(event.clientX, window.innerWidth - w - 8));
    const top = Math.max(8, Math.min(event.clientY, window.innerHeight - h - 8));
    menu.style.left = `${left}px`;
    menu.style.top = `${top}px`;
    menu.classList.add('open');
    return true;
}
function previewDownloadGroupItems(){
    // 分组预览：整组所有成员图片按阅读顺序打包。
    if(previewNavState.groupId){
        const group = nodes.find(n => n.id === previewNavState.groupId && isSmartGroupNode(n));
        if(group) return smartGroupImageRefs(group).map((r, index) => ({...r.item, __index:index}));
    }
    const node = nodes.find(n => n.id === previewNavState.nodeId);
    return (node?.images || [])
        .filter(item => item?.url)
        .map((item, index) => ({...item, __index:index}))
        .sort((a, b) => {
            const ga = a.grid || {};
            const gb = b.grid || {};
            const rowDiff = Number(ga.row ?? a.__index) - Number(gb.row ?? b.__index);
            if(rowDiff) return rowDiff;
            const colDiff = Number(ga.col ?? a.__index) - Number(gb.col ?? b.__index);
            return colDiff || a.__index - b.__index;
        });
}
// 把一组图片打包成 zip 下载（预览“下载全部”和分组小菜单“批量下载”共用）。
async function zipDownloadImageItems(title, items){
    const list = (items || [])
        .map(item => item ? ({...item, url:smartOriginalMediaUrl(item)}) : null)
        .filter(item => item?.url);
    if(!list.length) return;
    try {
        const filename = safeExportFileName(`${title || 'image-group'}.zip`, 'image-group.zip');
        const response = await fetch('/api/canvas-assets/download', {
            method:'POST',
            headers:{'Content-Type':'application/json'},
            body:JSON.stringify({
                filename,
                urls:list.map(item => item.url).filter(Boolean),
                items:list.map((item, index) => ({url:item.url, name:downloadNameForMediaItem(item, `image-${String(index + 1).padStart(2, '0')}`)}))
            })
        });
        if(!response.ok) throw new Error((await response.text()) || '批量下载失败');
        const blob = await response.blob();
        const href = URL.createObjectURL(blob);
        const link = document.createElement('a');
        link.href = href;
        link.download = filename;
        document.body.appendChild(link);
        link.click();
        link.remove();
        setTimeout(() => URL.revokeObjectURL(href), 1200);
    } catch(e) {
        toast((e.message || '批量下载失败').slice(0, 160));
    }
}
