function sanitizePromptRichHtml(html=''){
    const temp = document.createElement('template');
    temp.innerHTML = String(html || '');
    const cleanChildren = parent => [...parent.childNodes].map(cleanNode).join('');
    const cleanNode = node => {
        if(node.nodeType === Node.TEXT_NODE) return escapeHtml(node.textContent || '');
        if(node.nodeType !== Node.ELEMENT_NODE) return '';
        const tag = node.tagName.toLowerCase();
        if(tag === 'br') return '<br>';
        const inner = cleanChildren(node);
        if(tag === 'div' || tag === 'p') return inner ? `${inner}<br>` : '<br>';
        const style = node.style || {};
        const rawFontSize = Number.parseFloat(style.fontSize || '');
        const fontSize = rawFontSize > 0 ? Math.max(9, Math.min(28, rawFontSize)) : 0;
        const fontWeight = Number.parseInt(style.fontWeight || '', 10);
        const bold = tag === 'b' || tag === 'strong' || fontWeight >= 600 || String(style.fontWeight || '').toLowerCase() === 'bold';
        const italic = tag === 'i' || tag === 'em' || String(style.fontStyle || '').toLowerCase() === 'italic';
        const parts = [];
        if(fontSize) parts.push(`font-size:${fontSize}px`);
        if(bold) parts.push('font-weight:700');
        if(italic) parts.push('font-style:italic');
        return parts.length ? `<span data-prompt-rich="1" style="${escapeAttr(parts.join(';'))}">${inner}</span>` : inner;
    };
    return cleanChildren(temp.content).replace(/(<br>){3,}/g, '<br><br>').replace(/(?:<br>)+$/g, '');
}
function promptNodeRichHtml(node){
    const plain = String(node?.text || '');
    const rich = String(node?.textHtml || '');
    if(rich && promptRichPlainTextFromHtml(rich).trim() === plain.trim()) return sanitizePromptRichHtml(rich);
    return escapeHtml(plain);
}
function placeCaretAtEnd(el){
    if(!el) return;
    el.focus();
    const range = document.createRange();
    range.selectNodeContents(el);
    range.collapse(false);
    const sel = window.getSelection();
    sel?.removeAllRanges();
    sel?.addRange(range);
}
