    if(!ref) return smartRunEmptyBodyHtml(node);
    const kind = mediaKindForItem(ref);
    // 2026-09-27 视频/图片/音频参考统一卡片化：全幅圆角铺满节点，无深灰外框留白；
    // 图片 onload / 视频 loadedmetadata 后徽标换成真实分辨率。
    const media = kind === 'video'
        ? smartUploadVideoHtml(ref, 768, 'onloadedmetadata="smartRunRefVideoOnload(this)"', {noPoster:true})
        : kind === 'audio'
        ? `<div class="smart-run-ref-audio"><span class="smart-run-ref-audio-icon"><i data-lucide="audio-lines"></i></span><span class="smart-run-ref-audio-name">${escapeHtml(ref.name || '音频')}</span><audio src="${escapeAttr(displayMediaUrl(ref))}" data-url="${escapeAttr(ref.url || '')}" controls preload="metadata"></audio></div>`
        : isFileMediaItem(ref)
