// 图片卡片加载完后把角标从「参考图1」换成真实分辨率（对齐参考稿的 1152 × 2048 徽标），
// 并把分辨率写回参考项，让节点外框比例跟随图片分辨率。
function smartRunRefImgOnload(img){
    try{
        if(!img || !img.naturalWidth) return;
        const badge = img.closest('.smart-run-ref-media')?.querySelector('.smart-run-ref-badge');
        if(badge) badge.textContent = `${img.naturalWidth} × ${img.naturalHeight}`;
        const outsideBadge = img.closest('.node-body')?.querySelector(':scope > .image-resolution-badge-outside');
        if(outsideBadge) outsideBadge.textContent = `${img.naturalWidth} x ${img.naturalHeight}`;
        const nodeEl = img.closest('.image-node');
        const node = nodeEl ? nodes.find(n => n.id === nodeEl.dataset.id) : null;
        if(!node) return;
        const ref = smartRunNodePreviewRefs(node).find(item => item?.url && (item.kind || mediaKindForItem(item)) === 'image');
        if(ref){ ref.width = img.naturalWidth; ref.height = img.naturalHeight; }
        const prev = node.refMediaSize;
        if(!prev || prev.w !== img.naturalWidth || prev.h !== img.naturalHeight){
            node.refMediaSize = {w:img.naturalWidth, h:img.naturalHeight};
            render();
            scheduleSave();
        }
    }catch(err){}
}
// 视频参考卡片同理：元数据加载后徽标显示视频真实分辨率，
// 并把分辨率写回参考项 + 触发一次重排，让节点外框比例跟随视频分辨率。
function smartRunRefVideoOnload(video){
    try{
        if(!video || !video.videoWidth) return;
        const badge = video.closest('.smart-run-ref-media')?.querySelector('.smart-run-ref-badge');
        if(badge) badge.textContent = `${video.videoWidth} × ${video.videoHeight}`;
        const outsideBadge = video.closest('.node-body')?.querySelector(':scope > .image-resolution-badge-outside');
        if(outsideBadge) outsideBadge.textContent = `${video.videoWidth} x ${video.videoHeight}`;
        const nodeEl = video.closest('.image-node');
        const node = nodeEl ? nodes.find(n => n.id === nodeEl.dataset.id) : null;
        if(!node) return;
        const ref = smartRunNodePreviewRefs(node).find(item => item?.url && (item.kind || mediaKindForItem(item)) === 'video');
        if(ref){ ref.width = video.videoWidth; ref.height = video.videoHeight; }
        const prev = node.refMediaSize;
        if(!prev || prev.w !== video.videoWidth || prev.h !== video.videoHeight){
            node.refMediaSize = {w:video.videoWidth, h:video.videoHeight};
            render();
            scheduleSave();
        }
    }catch(err){}
}
function smartNodeRunNoticeHtml(node){
    const error = String(node?.runError || '').trim();
    const warning = String(node?.runWarning || '').trim();
    const message = error || warning;
    if(!message) return '';
    const kind = error ? 'error' : 'warning';
    const title = error ? '生成失败' : '提示';
    return `<div class="smart-node-run-notice is-${kind}" role="alert">
        <div class="smart-node-run-notice-head"><i data-lucide="${error ? 'circle-alert' : 'triangle-alert'}"></i><strong>${title}</strong></div>
        <div class="smart-node-run-notice-text">${escapeHtml(message)}</div>
    </div>`;
}
function smartNodeBodyWithNotice(node, body){
    const notice = smartNodeRunNoticeHtml(node);
    return notice ? `<div class="smart-node-body-stack">${body}${notice}</div>` : body;
}
function setSmartNodeRunNotice(node, message, kind='warning'){
    const target = liveSmartNode(node);
    const text = String(message || '').trim();
    if(!target || !text) return;
    if(kind === 'error'){
        target.runError = text;
        delete target.runWarning;
    } else {
        target.runWarning = text;
        delete target.runError;
    }
    scheduleSave();
    render();
}
function clearSmartNodeRunNotice(node){
    const target = liveSmartNode(node);
    if(!target) return;
    delete target.runError;
    delete target.runWarning;
}
