function generationProgressView(node){
    const raw = Number(node?.generationProgressPercent);
    const actualPercent = Number.isFinite(raw) ? Math.max(0, Math.min(100, Math.round(raw))) : 0;
    let displayPercent = actualPercent;
    if(node && (node.pending || node.running || node.queued) && actualPercent < 100){
        const started = Number(node.runStartedAt || 0) || nowMs();
        const elapsedSec = Math.max(0, (nowMs() - started) / 1000);
        const eased = Math.round(95 * (1 - Math.exp(-elapsedSec / 38)));
        displayPercent = Math.max(actualPercent, Math.min(95, eased));
    }
    const value = Number(node?.generationProgressValue || 0);
    const total = Number(node?.generationProgressTotal || 0);
    const message = String(node?.generationProgressMessage || '生成中');
    const detail = total > 0 ? `${value}/${total}` : message;
    return {percent:displayPercent, actualPercent, message, detail};
}
function pendingGridItems(node, count=1){
    const limit = Math.max(0, Number(count) || 0);
    if(!node || !limit) return [];
    const stopped = new Set(Array.isArray(node.stoppedTaskIds) ? node.stoppedTaskIds : []);
    const placeholders = (Array.isArray(node.pendingPlaceholders) ? node.pendingPlaceholders : [])
        .filter(item => item && !item.failed && !item.querying)
        .map(item => ({
            id:item.id || item.taskId || '',
            taskId:item.taskId || '',
            startedAt:Number(item.startedAt || node.runStartedAt || 0) || nowMs(),
            index:Number.isFinite(Number(item.index)) ? Number(item.index) : 0,
            outputW:Number(item.outputW || item.width || item.w || 0) || 0,
            outputH:Number(item.outputH || item.height || item.h || 0) || 0,
            ratio:String(item.ratio || '').trim()
        }));
    const placeholderByTaskId = new Map(placeholders.filter(item => item.taskId).map(item => [item.taskId, item]));
    const tasks = smartPendingTasks(node)
        .filter(task => task && task.taskId && !task.failed && !task.querying && !stopped.has(task.taskId))
        .map(task => {
            const placeholder = placeholderByTaskId.get(task.taskId);
            return {
                id:task.taskId,
                taskId:task.taskId,
                startedAt:Number(task.startedAt || task.createdAt || placeholder?.startedAt || node.runStartedAt || 0) || nowMs(),
                index:Number.isFinite(Number(task.index)) ? Number(task.index) : Number(placeholder?.index || 0),
                outputW:Number(task.outputW || task.width || task.w || placeholder?.outputW || 0) || 0,
                outputH:Number(task.outputH || task.height || task.h || placeholder?.outputH || 0) || 0,
                ratio:String(task.ratio || placeholder?.ratio || '').trim()
            };
        });
    const items = placeholders.length ? placeholders : tasks;
    while(items.length < limit){
        items.push({id:'', taskId:'', startedAt:Number(node.runStartedAt || 0) || nowMs()});
    }
    return items.sort((a, b) => Number(a.index || 0) - Number(b.index || 0) || Number(a.startedAt || 0) - Number(b.startedAt || 0)).slice(0, limit);
}
function pendingThumbRatioOf(node, item=null){
    const itemW = Number(item?.outputW || item?.width || item?.w || 0);
    const itemH = Number(item?.outputH || item?.height || item?.h || 0);
    if(itemW > 0 && itemH > 0) return {w:Math.round(itemW), h:Math.round(itemH)};
    if(item?.ratio && /^\d+(?:\.\d+)?\s*:\s*\d+(?:\.\d+)?$/.test(item.ratio)){
        const [rw, rh] = item.ratio.split(':').map(Number);
        if(rw > 0 && rh > 0) return {w:rw, h:rh};
    }
    // 兼容旧占位数据：没有提交尺寸快照时再读取节点当前运行参数。
    const runSettings = node?.runSettings || null;
    if(runSettings){
        const refs = node ? generationTargetReferenceImagesFor(node, false, smartLoopContext) : [];
        const requestSize = explicitRequestOutputSizeForPending({settings:runSettings, refs});
        if(requestSize?.w > 0 && requestSize?.h > 0){
            return {w:Math.round(requestSize.w), h:Math.round(requestSize.h)};
        }
    }
    const box = node?.pendingBaseBox || null;
    const w = Number(box?.w || box?.width || 0);
    const h = Number(box?.h || box?.height || 0);
    if(!(w > 0 && h > 0)) return null;
    return {w:Math.max(1, Math.round(w)), h:Math.max(1, Math.round(h))};
}
function pendingThumbRatioStyle(node, item=null){
    const ratio = pendingThumbRatioOf(node, item);
    if(!ratio) return {style:'', badge:''};
    const label = item?.ratio || ratioTextFromDimensions(ratio.w, ratio.h);
    return {
        style:` style="max-width:100%;max-height:100%"`,
        badge:`<span class="pending-ratio-badge" style="position:absolute;left:6px;bottom:6px;z-index:2;padding:2px 7px;border-radius:999px;background:rgba(0,0,0,.55);color:#fff;font-size:11px;line-height:1.4;pointer-events:none">${escapeHtml(label)}</span>`
    };
}
function pendingThumbSizeStyle(node, item=null, edge=96){
    const ratio = pendingThumbRatioOf(node, item);
    const maxEdge = Math.max(48, Math.round(Number(edge) || 96));
    if(!ratio?.w || !ratio?.h) return ` style="--thumb-w:${maxEdge}px;--thumb-h:${maxEdge}px;--thumb-aspect:1"`;
    const aspect = Math.max(0.05, Math.min(20, Number(ratio.w) / Math.max(1, Number(ratio.h))));
    const w = aspect >= 1 ? maxEdge : Math.max(40, Math.round(maxEdge * aspect));
    const h = aspect >= 1 ? Math.max(40, Math.round(maxEdge / aspect)) : maxEdge;
    return ` style="--thumb-w:${w}px;--thumb-h:${h}px;--thumb-aspect:${Math.round(ratio.w)}/${Math.round(ratio.h)}"`;
}
