            e.stopPropagation();
            const targetId = btn.dataset.h3Run || node.id;
            const target = nodes.find(n => n.id === targetId && isMinimaxH3Node(n));
            if(!target) return;
            const editor = el.querySelector('[data-h3-prompt]');
            if(editor) syncMinimaxH3PromptEditor(editor);
            selectedId = target.id;
            selectedIds = [];
            selectedImage = {nodeId:'', index:-1};
