    const limits = outpaintDisplayLimits();
    const old = {...cropState};
    let nextW = Math.max(baseW, Math.min(limits.w, old.w || baseW));
    let nextH = Math.max(baseH, Math.min(limits.h, old.h || baseH));
    if(nextW / nextH > ratio) nextH = nextW / ratio;
