    const canvasEl = document.createElement('canvas');
    canvasEl.width = Math.max(1, Number(rect?.sourceW) || sourceImg.naturalWidth || sourceImg.width || 1);
    canvasEl.height = Math.max(1, Number(rect?.sourceH) || sourceImg.naturalHeight || sourceImg.height || 1);
