function spatialAboveInputImagesFor(node){
    if(!node?.id) return [];
    const s = smartSettingsForNode(node) || {};
    const engine = String(s.engine || '').toLowerCase();
    if(!isApiLikeEngine(engine) || s.apiKind !== 'image') return [];
    if(inputImagesFor(node).some(img => img?.url)) return [];
    if(manualReferenceImagesFor(node).some(img => img?.url)) return [];
    const targetRect = nodeRect(node);
    let best = null;
    nodes.forEach(candidate => {
        if(!candidate || candidate.id === node.id) return;
        if(!isSmartImageNode(candidate)) return;
        const imgs = candidate.images || [];
        if(!imgs.some(img => img?.url)) return;
        const rect = nodeRect(candidate);
        const overlap = Math.min(targetRect.x + targetRect.width, rect.x + rect.width) - Math.max(targetRect.x, rect.x);
        if(overlap < 40) return;
        const gap = targetRect.y - (rect.y + rect.height);
        if(gap < -24) return;
        if(!best || gap < best.gap) best = {candidate, gap};
    });
    if(!best) return [];
    return imagesForNode(best.candidate)
        .filter(img => img?.url)
        .map(img => ({...img, explicitInput:true, spatialRef:true}));
}
