    const pendingStartedAt = nowMs();
    const outputW = Number(options.outputW || 0) || Number(baseBox?.w || 0) || 0;
    const outputH = Number(options.outputH || 0) || Number(baseBox?.h || 0) || 0;
    const outputRatio = String(options.outputRatio || (outputW > 0 && outputH > 0 ? ratioTextFromDimensions(outputW, outputH) : '')).trim();
