                if(!placeholder){
                    placeholder = {id:uid('pending'), runToken:pendingRunToken, index, startedAt:task.startedAt};
                    nextPlaceholders.push(placeholder);
                }
                placeholder.taskId = task.taskId;
                placeholder.kind = task.kind;
                placeholder.providerId = task.providerId;
