function imageReplaceTargetFromPoint(clientX, clientY, sourceNodeId='', sourceImageIndex=-1){
    const hit = document.elementFromPoint(clientX, clientY);
    const mediaEl = hit?.closest?.('.thumb-item,.image-wrap,.upload-preview-card');
    const nodeEl = mediaEl?.closest?.('.image-node') || hit?.closest?.('.image-node');
    if(!nodeEl?.dataset?.id) return null;
    const ownerId = mediaEl?.dataset?.refNodeId || nodeEl.dataset.id;
    const owner = nodes.find(n => n.id === ownerId);
    if(!owner || !Array.isArray(owner.images) || !owner.images.length) return null;
    if(!isSmartImageNode(owner) && !isSmartGroupNode(owner)) return null;
    const rawIndex = mediaEl ? (mediaEl.dataset.refImageIndex ?? mediaEl.dataset.imageIndex ?? '0') : '0';
    const index = Math.max(0, Math.min(owner.images.length - 1, Number(rawIndex) || 0));
    if(owner.id === sourceNodeId && index === Number(sourceImageIndex)) return null;
    if(!isImageReplaceableMedia(owner.images[index])) return null;
    return {node:owner, index, nodeEl, mediaEl};
}
