        if(!ref?.url) return ref;
        const refIndex = Number(ref.imageIndex);
        const sameSlot = ref.nodeId === targetNode.id && Number.isFinite(refIndex) && refIndex === Number(imageIndex);
        const sameConnectedUrl = !ref.nodeId && oldUrl && ref.url === oldUrl;
        if(!sameSlot && !sameConnectedUrl) return ref;
        changed = true;
