function smartGroupTargetForDraggedNode(draggedNode){
    // 允许把一个分组拖进另一个分组（拖来的分组的成员会作为输入并入目标分组）。自身/被拖分组及其成员已在 excluded 中排除。
    // 图片拖入组时不只看中心点：只要与组有明确重叠，也视为“拖到组上”，更贴近用户把图片搭到组边缘释放的操作。
    if(!draggedNode) return null;
    const r = nodeRect(draggedNode);
    const excluded = new Set([draggedNode.id, ...(dragState?.groupIds || [])]);
    const cx = r.x + r.width / 2;
    const cy = r.y + r.height / 2;
    const overlapScore = targetRect => {
        const ix = Math.max(0, Math.min(r.x + r.width, targetRect.x + targetRect.width) - Math.max(r.x, targetRect.x));
        const iy = Math.max(0, Math.min(r.y + r.height, targetRect.y + targetRect.height) - Math.max(r.y, targetRect.y));
        const overlap = ix * iy;
        if(!overlap) return 0;
        const draggedArea = Math.max(1, r.width * r.height);
        const targetArea = Math.max(1, targetRect.width * targetRect.height);
        return Math.max(overlap / draggedArea, overlap / targetArea);
    };
    const groups = nodes
        .filter(node => isSmartGroupNode(node) && !excluded.has(node.id))
        .map(group => ({group, rect:nodeRect(group)}))
        .map(item => ({
            ...item,
            centerHit:cx >= item.rect.x && cx <= item.rect.x + item.rect.width && cy >= item.rect.y && cy <= item.rect.y + item.rect.height,
            overlap:overlapScore(item.rect)
        }))
        .filter(item => item.centerHit || item.overlap >= 0.08);
    if(!groups.length) return null;
    groups.sort((a, b) => Number(b.centerHit) - Number(a.centerHit) || b.overlap - a.overlap || (nodes.indexOf(b.group) - nodes.indexOf(a.group)));
    return groups[0].group;
}
