function setSmartQuickEngine(engine, apiKind='image'){
    const generationRefs = selectedCanvasMediaRefsForGeneration();
    const node = ensureSmartQuickRunnableNode();
    if(!node) return;
    delete node.fixedEngine;
    applyGenerationRefsToNode(node, generationRefs);
    const panelKind = engine === 'comfy' ? 'comfy' : (apiKind === 'video' || engine === 'h3' ? 'video' : 'image');
    settings = smartPanelSettingsForKind(panelKind, node);
    settings.engine = engine;
    if(isApiLikeEngine(engine)) settings.apiKind = apiKind === 'video' ? 'video' : 'image';
    applyRecentSmartSettingsForCurrentMode();
    settings.engine = engine;
    if(isApiLikeEngine(engine)) settings.apiKind = apiKind === 'video' ? 'video' : 'image';
    if(engine === 'comfy'){
        settings.comfyMode = settings.comfyMode || 'text';
        settings.apiKind = 'image';
    }
    node.runSettings = settingsForStorage(settings);
    activeSmartPanelKind = panelKind;
    rememberSmartPanelSettings(panelKind, settings, node);
    node.title = smartGenerationNodeTitle(node);
    syncApiKindToggleVisibility();
    renderDynamicParams();
    activeComposerSubject = node;
    lastComposerNodeId = '';
    render();
    updateComposer();
    scheduleSave();
}
function runSmartQuickAction(action){
    if(action === 'upload') return openSmartQuickUpload();
    if(action === 'prompt') return createSmartQuickPrompt(false);
    if(action === 'loop') return createSmartQuickLoop();
    if(action === 'llm') return createSmartQuickPrompt(true);
    if(action === 'api') return setSmartQuickEngine('api', 'image');
    if(action === 'modelscope') return setSmartQuickEngine('modelscope', 'image');
    if(action === 'video') return setSmartQuickEngine('api', 'video');
    if(action === 'runninghub') return setSmartQuickEngine('runninghub', 'image');
    if(action === 'comfy') return setSmartQuickEngine('comfy', 'image');
}
