function mouseButtonStillPressed(event, button=0){
    if(event?.buttons == null) return true;
    const buttons = Number(event.buttons);
    if(!Number.isFinite(buttons)) return true;
    const mask = button === 1 ? 4 : button === 2 ? 2 : 1;
    return Boolean(buttons & mask);
}
