function removeDetachedThumbFromSource(info){
    if(!info || info.copy) return false;
    const source = nodes.find(n => n.id === info.nodeId);
    if(!source || !Array.isArray(source.images) || !source.images.length) return false;
    if(Number.isFinite(Number(info.sourceBeforeCount)) && source.images.length < Number(info.sourceBeforeCount)) return false;
    const expectedIndex = Number(info.imgIndex);
    const sourceUrl = String(info.url || '');
    let removeIndex = -1;
    if(Number.isInteger(expectedIndex) && expectedIndex >= 0 && expectedIndex < source.images.length){
        const img = source.images[expectedIndex];
        if(!sourceUrl || img?.url === sourceUrl) removeIndex = expectedIndex;
    }
    if(removeIndex < 0 && sourceUrl) removeIndex = source.images.findIndex(img => img?.url === sourceUrl);
    if(removeIndex < 0) return false;
    source.mediaClearedAt = Date.now();
    source.images.splice(removeIndex, 1);
    markSmartNodeImagesEdited(source);
    if(isSmartGroupNode(source)){
        arrangeSmartGroupMembers(source, {skipUndo:true, syncDom:true});
    } else {
        if(source.images.length <= 1 || (imageGroupSupportsFreeLayout(source) && !source.images.some(img => Number.isFinite(Number(img?.layout_x)) && Number.isFinite(Number(img?.layout_y))))){
            clearImageGroupFreeLayout(source);
        }
        if(source.images.length <= 1){
            source.title = source.images.length ? 'Image' : (source.title || 'Image');
            delete source.w;
            delete source.h;
            inheritNodeMetaFromImage(source);
        }
    }
    return true;
}
// 节点拖动的 rAF 合帧状态（见 applyDragMoveFrame / window.onmousemove）
let dragMovePendingEvent = null;
let dragMoveRafId = 0;
window.onmousemove = e => {
    lastMouseWorld = screenToWorld(e);
    if(smartMinimapDrag){
        e.preventDefault();
        centerViewportOnWorldPoint(minimapEventToWorld(e));
        return;
    }
    if(portDragState){
        e.preventDefault();
        const p = screenToWorld(e);
        portDragState.currentWorld = p;
        portDragState.moved = true;
        updatePortDragTargetFromEvent(portDragState, e);
        updatePortDragVisual();
        return;
    }
    if(promptResizeState){
        e.preventDefault();
        const dy = e.clientY - promptResizeState.startY;
        settings.promptH = Math.max(60, Math.min(380, promptResizeState.startH + dy));
        promptInput.style.setProperty('--prompt-h', `${settings.promptH}px`);
        persistActiveSmartSettings();
        return;
    }
    if(selectionState){
        e.preventDefault();
        updateSelectionBox(e);
        return;
    }
    if(previewCompareDrag){
        e.preventDefault();
        setPreviewComparePos(e.clientX);
        return;
    }
    if(panoramaState.drag){
        e.preventDefault();
        const dx = e.clientX - panoramaState.drag.clientX;
        const dy = e.clientY - panoramaState.drag.clientY;
        panoramaState.yaw = panoramaState.drag.yaw - dx * 0.18;
        panoramaState.pitch = Math.max(-85, Math.min(85, panoramaState.drag.pitch + dy * 0.18));
        document.getElementById('previewStage')?.classList.add('panning');
        return;
    }
    if(previewPanDrag){
        const stage = document.getElementById('previewStage');
        previewPan = {
            x:previewPanDrag.startX + (e.clientX - previewPanDrag.clientX),
            y:previewPanDrag.startY + (e.clientY - previewPanDrag.clientY)
        };
        stage?.classList.add('panning');
        applyPreviewTransform();
        return;
    }
    if(imageEditPanDrag){
        const stage = document.getElementById('imageEditStage');
        if(stage){
            stage.scrollLeft = imageEditPanDrag.scrollLeft - (e.clientX - imageEditPanDrag.clientX);
            stage.scrollTop = imageEditPanDrag.scrollTop - (e.clientY - imageEditPanDrag.clientY);
        }
        return;
    }
    if(cropDrag && cropState){
        const dx = e.clientX - cropDrag.sx;
        const dy = e.clientY - cropDrag.sy;
        if(cropDrag.mode === 'move'){
            cropState.x = cropDrag.start.x + dx;
            cropState.y = cropDrag.start.y + dy;
        } else if(cropDrag.mode === 'image'){
            cropState.x = cropDrag.start.x + dx;
            cropState.y = cropDrag.start.y + dy;
        } else if(String(cropDrag.mode || '').startsWith('outpaint-')){
            resizeOutpaintFromDrag(dx, dy);
        } else {
            resizeCropFromDrag(dx, dy);
        }
        clampCrop();
        renderCropBox();
        return;
    }
    if(resizeState){
        const node = nodes.find(n => n.id === resizeState.id);
        if(!node) return;
        const dx = (e.clientX - resizeState.startX) / viewport.scale;
        const dy = (e.clientY - resizeState.startY) / viewport.scale;
        const minW = node.type === 'smart-prompt' ? PROMPT_NODE_MIN_WIDTH : node.type === 'smart-loop' ? 252 : node.type === 'smart-group' ? SMART_GROUP_MIN_WIDTH : 48;
        const minH = node.type === 'smart-prompt' ? PROMPT_NODE_MIN_HEIGHT : node.type === 'smart-loop' ? 132 : node.type === 'smart-group' ? SMART_GROUP_MIN_HEIGHT : 48;
        if(node.type === 'smart-group' && smartGroupImageRefs(node).some(ref => ref.item?.url)){
            // 图片分组：和普通节点一样直接改 w/h，缩略图网格按新尺寸实时重排。不要走下面的“成员缩放”那套，
            // 否则拖动过程里会按成员包围盒/缩放比例收缩，松手才回到拖动宽度（用户反馈的“变宽时先缩小”）。
            node.smartGroupManualSize = true;
            node.w = Math.max(minW, Math.round(resizeState.startW + dx));
            node.h = Math.max(minH, Math.round(resizeState.startH + dy));
            if(smartGroupCompactMembers(node).length) arrangeSmartGroupMembers(node, {skipUndo:true, syncDom:true});
            updateNodeElementDuringResize(node);
            return;
        }
        if(node.type === 'smart-group'){
            // 分组当“画布中的画布”：拖手柄按宽度方向算出统一缩放比例，组内所有成员（图片+提示词）按相对手势
            // 起点的快照整体缩放+重排，然后把分组框自动收紧到成员的包围盒——盒子始终贴合内容，右侧不会留空白。
            const startZoom = resizeState.startZoom || 1;
            // 目标框宽 = 手柄拖出的框宽；缩放映射以“贴合内容的框宽”为基准，保证两个阶段都线性跟随手柄、衔接连续。
            const targetW = resizeState.startW + dx;
            const fitBase = resizeState.contentFitW || resizeState.startW || 1;
            const desiredZoom = startZoom * (targetW / fitBase);
            // 成员缩放上限 SMART_GROUP_MAX_MEMBER_ZOOM（默认 1=原始尺寸）：到上限就不再放大成员，改为让分组框继续扩大。
            const effectiveZoom = Math.max(0.2, Math.min(SMART_GROUP_MAX_MEMBER_ZOOM, desiredZoom));
            const memberRatio = effectiveZoom / startZoom;
            const capped = desiredZoom > SMART_GROUP_MAX_MEMBER_ZOOM;
            node._memberZoom = effectiveZoom;
            const gx = Number(node.x) || 0, gy = Number(node.y) || 0;
            const SMART_GROUP_PAD = 16;
            let maxRight = gx, maxBottom = gy, hasMember = false;
            (resizeState.members || []).forEach(snap => {
                const member = nodes.find(n => n.id === snap.id);
                if(!member) return;
                hasMember = true;
                member.x = gx + (snap.sx - gx) * memberRatio;
                member.y = gy + (snap.sy - gy) * memberRatio;
                if(snap.isImage){
                    delete member.w;
                    delete member.h;
                    if(!Number.isFinite(Number(member.scale)) || Number(member.scale) <= 0) member.scale = MEDIA_NODE_DEFAULT_SCALE;
                } else {
                    member.w = Math.max(40, Math.round(snap.sw * memberRatio));
                    member.h = Math.max(40, Math.round(snap.sh * memberRatio));
                }
                const memberRect = nodeRect(member);
                maxRight = Math.max(maxRight, member.x + memberRect.width);
                maxBottom = Math.max(maxBottom, member.y + memberRect.height);
                const memberEl = world.querySelector(`.image-node[data-id="${CSS.escape(member.id)}"]`);
                if(memberEl){
                    memberEl.style.left = `${member.x}px`;
                    memberEl.style.top = `${member.y}px`;
                }
                updateNodeElementDuringResize(member);
            });
            if(capped || !hasMember){
                // 成员已到上限（或空分组）：分组框随手柄继续扩大，成员不再放大。
                node.w = Math.max(minW, Math.round(resizeState.startW + dx));
                node.h = Math.max(minH, Math.round(resizeState.startH + dy));
            } else {
                // 未到上限：分组框收紧到成员包围盒，贴合内容无空白。
                node.w = Math.max(minW, Math.round(maxRight - gx + SMART_GROUP_PAD));
                node.h = Math.max(minH, Math.round(maxBottom - gy + SMART_GROUP_PAD));
            }
            node.scale = 1;
            updateNodeElementDuringResize(node);
            return;
        }
        node.w = Math.max(minW, Math.round(resizeState.startW + dx));
        node.h = Math.max(minH, Math.round(resizeState.startH + dy));
        node.scale = 1;
        updateNodeElementDuringResize(node, {refreshInteraction:node.type !== 'smart-prompt'});
        return;
    }
    if(llmInstructionResizeState){
        const node = nodes.find(n => n.id === llmInstructionResizeState.id);
        if(!node) return;
        const dy = (e.clientY - llmInstructionResizeState.startY) / viewport.scale;
        const newInstrH = Math.max(PROMPT_LLM_INSTRUCTION_MIN_H, Math.min(PROMPT_LLM_INSTRUCTION_MAX_H, Math.round(llmInstructionResizeState.startH + dy)));
        node.llmInstructionHeight = newInstrH;
        // 只把“指令框的高度变化量”叠加到节点总高度上，保留用户手动拉大的上方区域，避免上方被重置变小。
        node.h = Math.max(promptNodeExpandedHeight(node), Math.round(llmInstructionResizeState.startNodeH + (newInstrH - llmInstructionResizeState.startH)));
        node.w = Math.max(Number(node.w) || 0, 316);
        node.scale = 1;
        updateNodeElementDuringResize(node);
        const ta = world.querySelector(`.image-node[data-id="${CSS.escape(node.id)}"] .prompt-llm-instruction`);
        if(ta) ta.style.height = `${promptLlmInstructionHeight(node)}px`;
        return;
    }
    if(promptSplitResizeState){
        const node = nodes.find(n => n.id === promptSplitResizeState.id);
        if(!node) return;
        const dy = (e.clientY - promptSplitResizeState.startY) / viewport.scale;
        const newPreviewH = Math.max(PROMPT_SPLIT_PREVIEW_MIN_H, Math.min(PROMPT_SPLIT_PREVIEW_MAX_H, Math.round(promptSplitResizeState.startH + dy)));
        node.promptSplitPreviewHeight = newPreviewH;
        node.h = Math.max(promptNodeMinHeight(node), Math.round(promptSplitResizeState.startNodeH + (newPreviewH - promptSplitResizeState.startH)));
        node.w = Math.max(Number(node.w) || 0, 316);
        node.scale = 1;
        updateNodeElementDuringResize(node);
        const list = world.querySelector(`.image-node[data-id="${CSS.escape(node.id)}"] .prompt-node-segments`);
        if(list) list.style.height = `${promptNodeSplitPreviewHeight(node)}px`;
        return;
    }
    if(imageReplaceDragState){
        updateImageReplaceDragVisual(e);
        return;
    }
    if(thumbDragState){
        const dx = e.clientX - thumbDragState.startX;
        const dy = e.clientY - thumbDragState.startY;
        const source = nodes.find(n => n.id === thumbDragState.nodeId);
        const movedFarEnough = Math.abs(dx) + Math.abs(dy) > 6;
        const canLeaveDetach = (() => {
            if(!thumbDragState.detachOnLeave) return true;
            if(!source) return false;
            const point = screenToWorld(e);
            const r = nodeRect(source);
            // 2026-10-12（用户要求：拖宫格组容易误触拖子图）：分离阈值 8 → 24，
            // 子图要拖出组框 24 世界像素才算「拆出」，路过边距带/贴边拖动不再瞬间分离。
            const pad = 24;
            return point.x < r.x - pad || point.x > r.x + r.width + pad || point.y < r.y - pad || point.y > r.y + r.height + pad;
        })();
        if(!thumbDragState.detached && movedFarEnough && source && !canLeaveDetach){
            const hit = document.elementFromPoint(e.clientX, e.clientY);
            const targetItem = hit?.closest?.('.thumb-item');
            const targetNodeEl = targetItem?.closest?.('.image-node');
            const targetNodeId = targetNodeEl?.dataset?.id || '';
            const targetIndex = Number(targetItem?.dataset?.imageIndex);
            if(targetNodeId === source.id && Number.isInteger(targetIndex) && targetIndex !== thumbDragState.imgIndex){
                const placement = imageThumbDropPlacement(targetItem, e);
                if(reorderImageThumb(source.id, thumbDragState.imgIndex, targetIndex, placement)){
                    thumbDragState.reordered = true;
                    const refreshed = nodes.find(n => n.id === source.id);
                    const nextIndex = refreshed?.images?.findIndex(img => img?.url === thumbDragState.url);
                    if(Number.isInteger(nextIndex) && nextIndex >= 0) thumbDragState.imgIndex = nextIndex;
                }
                suppressImageClickUntil = Date.now() + 260;
                return;
            }
        }
        if(!thumbDragState.detached && movedFarEnough && canLeaveDetach){
            const canDetachThumb = source && (isSmartGroupNode(source) ? (source.images || []).length >= 1 : (source.images || []).length > 1);
            if(canDetachThumb){
                const sourceImg = source.images[thumbDragState.imgIndex];
                if(sourceImg){
                    commitPendingUndo();
                    undoSuppressed = true;
                    const img = stripImageGenerationMeta({...sourceImg});
                    applyNodeMetaToImage(img, source);
                    if(!thumbDragState.copy){
                        removeDetachedThumbFromSource(thumbDragState);
                    }
                    const point = screenToWorld(e);
                    selectedId = '';
                    selectedImage = {nodeId:'', index:-1};
                    const newNode = createImageNodeAt(point, [img], {select:false, skipUndo:true});
                    undoSuppressed = false;
                    dragState = {
                        id:newNode.id,
                        startX:e.clientX,
                        startY:e.clientY,
                        ox:newNode.x,
                        oy:newNode.y,
                        thumbDetached:true,
                        sourceThumb:{
                            nodeId:source.id,
                            imgIndex:thumbDragState.imgIndex,
                            sourceBeforeCount:thumbDragState.sourceBeforeCount,
                            url:thumbDragState.url || sourceImg.url || '',
                            copy:thumbDragState.copy
                        }
                    };
                    thumbDragState.detached = true;
                    thumbFreeLayoutState = null;
                    render();
                }
            }
        }
        if(thumbDragState.detached){
            thumbDragState = null;
            thumbFreeLayoutState = null;
        }
        else return;
    }
    if(panState){
        if(!mouseButtonStillPressed(e, panState.button)){
            clearCanvasPanState();
            return;
        }
        const dx = e.clientX - panState.startX;
        const dy = e.clientY - panState.startY;
        if(Math.abs(dx) + Math.abs(dy) > 3){
            didPan = true;
            setCanvasPanPerformanceMode(true);
        }
        viewport.x = panState.ox + dx;
        viewport.y = panState.oy + dy;
        scheduleViewportApply({minimap:false, pan:true});
        return;
    }
    if(!dragState) return;
    if(!mouseButtonStillPressed(e, 0)){
        cancelLoosePointerInteractions();
        return;
    }
    // rAF 合帧（对齐参考实现的顺滑手感）：高回报率鼠标 1 秒能触发上百次 mousemove，
    // 每次都改节点坐标 + 命中检测 + 读布局（nodeRect）会连续强制同步重排，直接掉帧。
    // 这里只记录最新事件，用 requestAnimationFrame 每帧最多应用一次。
    dragMovePendingEvent = e;
    if(!dragMoveRafId) dragMoveRafId = requestAnimationFrame(applyDragMoveFrame);
};
// —— 节点拖动的每帧应用（由 window.onmousemove 通过 rAF 调度） ——
function applyDragMoveFrame(){
    dragMoveRafId = 0;
    const e = dragMovePendingEvent;
    dragMovePendingEvent = null;
    if(!e || !dragState) return;
    const node = nodes.find(n => n.id === dragState.id);
    if(!node) return;
    const moveDx = (e.clientX - dragState.startX) / viewport.scale;
    const moveDy = (e.clientY - dragState.startY) / viewport.scale;
    (dragState.group || [{id:dragState.id, ox:dragState.ox, oy:dragState.oy}]).forEach(item => {
        const n = nodes.find(x => x.id === item.id);
        if(!n) return;
        n.x = item.ox + moveDx;
        n.y = item.oy + moveDy;
    });
    // 2026-09-29 拖动对齐：与其他节点边/中心吸附，显示蓝色虚线参考线
    applyDragSnapAlign();
    if(assetLibraryOpen){
        const hit = document.elementFromPoint(e.clientX, e.clientY);
        if(hit && assetPanel?.contains(hit)){
            setAssetDragOver(true);
            clearDropHighlight();
            setAssetDragOver(true);
            return;
        }
        setAssetDragOver(false);
    }
    const draggedRect = nodeRect(node);
    const rawTarget = dragState.ctrlGroup
        ? (['smart-prompt','smart-loop'].includes(node.type)
            ? dragConnectTargetFor(node, screenToWorld(e))
            : rectOverlapNode(node.id, draggedRect.x, draggedRect.y, draggedRect.width, draggedRect.height, dragState.groupIds))
        : null;
    const target = isSmartGroupNode(rawTarget) ? null : rawTarget;
    setDropHighlight(target?.id || '');
    moveNodeElementsDuringDrag();
    positionPromptLlmComposer();
    updateLoopInsertPreview();
    if(target) setDropHighlight(target.id);
};
// —— 拖动对齐参考线（2026-09-29）：被拖节点与其他节点的边/中点 6px 内吸附，蓝色虚线指示 ——
let alignGuideLayer = null;
function ensureAlignGuideLayer(){
    if(alignGuideLayer && alignGuideLayer.isConnected) return alignGuideLayer;
    alignGuideLayer = document.createElement('div');
    alignGuideLayer.id = 'smartAlignGuides';
    alignGuideLayer.className = 'smart-align-guides';
    shell.appendChild(alignGuideLayer);
    return alignGuideLayer;
}
function hideAlignGuides(){
    if(alignGuideLayer && alignGuideLayer.firstChild) alignGuideLayer.innerHTML = '';
}
function showAlignGuides(vLines, hLines){
    const layer = ensureAlignGuideLayer();
    let html = '';
    const s = viewport.scale;
    (vLines || []).forEach(l => {
        const top = l.from * s + viewport.y;
        const h = Math.max((l.to - l.from) * s, 2);
        html += '<div class="smart-align-guide is-v" style="left:' + (l.x * s + viewport.x).toFixed(1) + 'px;top:' + top.toFixed(1) + 'px;height:' + h.toFixed(1) + 'px"></div>';
    });
    (hLines || []).forEach(l => {
        const left = l.from * s + viewport.x;
        const w = Math.max((l.to - l.from) * s, 2);
        html += '<div class="smart-align-guide is-h" style="top:' + (l.y * s + viewport.y).toFixed(1) + 'px;left:' + left.toFixed(1) + 'px;width:' + w.toFixed(1) + 'px"></div>';
    });
    if(layer.innerHTML !== html) layer.innerHTML = html;
}
function alignRectForNode(n){
    // 智能组节点的 images 由成员聚合而来，nodeRect 直接用 node.images 会算错尺寸
    if(isSmartGroupNode(n)){
        const imgs = smartGroupImageRefs(n).map(ref => ref.item);
        const layout = imageLayout(imgs, nodeScale(n), n);
        return {x:n.x || 0, y:n.y || 0, width:layout.width, height:layout.height};
    }
    return nodeRect(n);
}
function applyDragSnapAlign(){
    if(!dragState) return;
    const groupItems = dragState.group || [{id:dragState.id, ox:dragState.ox, oy:dragState.oy}];
    const draggedIds = new Set(dragState.groupIds || groupItems.map(item => item.id));
    const drs = [];
    groupItems.forEach(item => {
        const n = nodes.find(x => x.id === item.id);
        if(n) drs.push(alignRectForNode(n));
    });
    if(!drs.length){ hideAlignGuides(); return; }
    let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
    drs.forEach(r => {
        minX = Math.min(minX, r.x); minY = Math.min(minY, r.y);
        maxX = Math.max(maxX, r.x + r.width); maxY = Math.max(maxY, r.y + r.height);
    });
    const thresh = 6 / viewport.scale;
    // 候选目标：所有未被拖动的节点。
    // 工作流组成员需要能够互相吸附；拖动组内节点时只排除它所属的组框，
    // 不能再把同组兄弟节点当成“被大框完全包含的内部子节点”过滤掉。
    const draggedWorkflowGroupIds = new Set();
    nodes.filter(isWorkflowGroupNode).forEach(group => {
        const memberIds = new Set(workflowGroupMembers(group).map(member => member.id));
        if([...draggedIds].some(id => memberIds.has(id))) draggedWorkflowGroupIds.add(group.id);
    });
    const targetNodes = nodes.filter(n => (
        !draggedIds.has(n.id)
        && !(isWorkflowGroupNode(n) && draggedWorkflowGroupIds.has(n.id))
    ));
    let targets = targetNodes.map(n => ({node:n, ...alignRectForNode(n)})).filter(r => r.width > 2 && r.height > 2);
    targets = targets.filter(r => !targets.some(o => o !== r
        && o.width * o.height > r.width * r.height
        && o.x - 1 <= r.x && o.y - 1 <= r.y
        && o.x + o.width + 1 >= r.x + r.width && o.y + o.height + 1 >= r.y + r.height));
    const draggedEdgesX = [minX, (minX + maxX) / 2, maxX];
    const draggedEdgesY = [minY, (minY + maxY) / 2, maxY];
    let bestX = null, bestY = null;
    targets.forEach(t => {
        [t.x, t.x + t.width / 2, t.x + t.width].forEach(tv => {
            draggedEdgesX.forEach(dv => {
                const d = tv - dv;
                if(Math.abs(d) <= thresh && (!bestX || Math.abs(d) < Math.abs(bestX.d))) bestX = {d, x:tv, t};
            });
        });
        [t.y, t.y + t.height / 2, t.y + t.height].forEach(tv => {
            draggedEdgesY.forEach(dv => {
                const d = tv - dv;
                if(Math.abs(d) <= thresh && (!bestY || Math.abs(d) < Math.abs(bestY.d))) bestY = {d, y:tv, t};
            });
        });
    });
    if(!bestX && !bestY){ hideAlignGuides(); return; }
    const dx = bestX ? bestX.d : 0;
    const dy = bestY ? bestY.d : 0;
    groupItems.forEach(item => {
        const n = nodes.find(x => x.id === item.id);
        if(n){ n.x = (n.x || 0) + dx; n.y = (n.y || 0) + dy; }
    });
    const vLines = [], hLines = [];
    if(bestX){
        const t = bestX.t;
        vLines.push({x:bestX.x, from:Math.min(minY + dy, t.y), to:Math.max(maxY + dy, t.y + t.height)});
    }
    if(bestY){
        const t = bestY.t;
        hLines.push({y:bestY.y, from:Math.min(minX + dx, t.x), to:Math.max(maxX + dx, t.x + t.width)});
    }
    showAlignGuides(vLines, hLines);
}
function handleCanvasMouseUp(e){
    if(e && e.timeStamp && lastCanvasMouseUpStamp === e.timeStamp) return;
    if(e && e.timeStamp) lastCanvasMouseUpStamp = e.timeStamp;
    cleanupPortPointerCapture();
    document.body.classList.remove('smart-node-drag');
    document.body.classList.remove('smart-node-resize');
    if(portDragState){
        const drag = portDragState;
        portDragState = null;
        shell.classList.remove('port-dragging', 'batch-port-dragging');
        handlePortDrop(drag, e);
        return;
    }
    if(promptResizeState){ promptResizeState = null; scheduleSave(); }
    if(selectionState) finishSelection(e);
    if(previewCompareDrag) previewCompareDrag = false;
    if(panoramaState.drag){
        panoramaState.drag = null;
        document.getElementById('previewStage')?.classList.remove('panning');
    }
    if(previewPanDrag){
        previewPanDrag = null;
        document.getElementById('previewStage')?.classList.remove('panning');
    }
    if(imageEditPanDrag) imageEditPanDrag = null;
    if(cropDrag){
        document.getElementById('cropCanvas')?.classList.remove('dragging-image');
        cropDrag = null;
    }
    if(resizeState){
        const node = nodes.find(n => n.id === resizeState.id);
        const rect = node ? nodeRect(node) : null;
        const changed = rect && (Math.abs(rect.width - resizeState.startW) > 1 || Math.abs(rect.height - resizeState.startH) > 1);
        if(changed){
            if(node && isSmartImageNode(node)) node.appendPreviewManualSize = true;
            commitPendingUndo();
        } else { discardPendingUndo(); }
        resizeState = null;
        document.body.classList.remove('smart-prompt-node-resizing');
        if(changed) render();
        scheduleSave();
    }
    if(llmInstructionResizeState){
        const node = nodes.find(n => n.id === llmInstructionResizeState.id);
        const changed = node && promptLlmInstructionHeight(node) !== llmInstructionResizeState.startH;
        document.body.classList.remove('smart-node-resize', 'smart-llm-instr-resize');
        if(changed) commitPendingUndo(); else discardPendingUndo();
        llmInstructionResizeState = null;
        render();
        scheduleSave();
    }
    if(promptSplitResizeState){
        const node = nodes.find(n => n.id === promptSplitResizeState.id);
        const changed = node && promptNodeSplitPreviewHeight(node) !== promptSplitResizeState.startH;
        document.body.classList.remove('smart-node-resize', 'smart-prompt-split-resize');
        if(changed) commitPendingUndo(); else discardPendingUndo();
        promptSplitResizeState = null;
        render();
        scheduleSave();
    }
    if(imageReplaceDragState){
        finishImageReplaceDrag(e);
        return;
    }
    if(thumbDragState && thumbFreeLayoutState){
        commitPendingUndo();
        const node = nodes.find(n => n.id === thumbFreeLayoutState.nodeId);
        if(node) {
            reorderImageGroupByFreeLayout(node);
            clearImageGroupFreeLayout(node);
            markSmartNodeImagesEdited(node);
            selectedId = node.id;
            selectedIds = [];
            const activeIndex = node.images?.indexOf(thumbFreeLayoutState.imageRef);
            selectedImage = {nodeId:node.id, index:Number.isInteger(activeIndex) && activeIndex >= 0 ? activeIndex : Math.max(0, Math.min(thumbFreeLayoutState.imgIndex, (node.images || []).length - 1))};
        }
        thumbDragState = null;
        thumbFreeLayoutState = null;
        render();
        scheduleSave();
        return;
    }
    if(thumbDragState){
        if(thumbDragState.reordered || thumbDragState.detached) commitPendingUndo();
        else discardPendingUndo();
        thumbDragState = null;
    }
    if(panState) {
        panState = null;
        shell.classList.remove('panning');
        cancelScheduledViewportApply();
        applyViewport({minimap:true});
        finishCanvasPanPerformanceMode();
        scheduleSave();
        setTimeout(() => { didPan = false; }, 0);
    }
    if(smartMinimapDrag){
        smartMinimapDrag = false;
    }
    if(dragState){
        const draggedNode = nodes.find(n => n.id === dragState.id);
        let stateChanged = false;
        if(dragState.thumbDetached && removeDetachedThumbFromSource(dragState.sourceThumb)) stateChanged = true;
        const hit = document.elementFromPoint(e.clientX, e.clientY);
        const droppedOnAssetPanel = assetLibraryOpen && hit && assetPanel?.contains(hit);
        if(droppedOnAssetPanel && draggedNode && (draggedNode.images || []).length){
            const imagesToSave = (draggedNode.images || []).filter(img => img?.url);
            imagesToSave.forEach(img => addUrlToAssetLibrary(img.url, img.name || draggedNode.title || 'image'));
            (dragState.group || [{id:dragState.id, ox:dragState.ox, oy:dragState.oy}]).forEach(item => {
                const n = nodes.find(x => x.id === item.id);
                if(n){ n.x = item.ox; n.y = item.oy; }
            });
            setAssetDragOver(false);
            discardPendingUndo();
            clearDropHighlight();
            hideAlignGuides();
            dragState = null;
            document.body.classList.remove('smart-node-drag');
            render();
            scheduleSave();
            return;
        }
        const autoTarget = draggedNode && dragState.ctrlGroup ? dragConnectTargetFor(draggedNode, screenToWorld(e)) : null;
        const insertHit = draggedNode?.type === 'smart-loop' && dragState.ctrlGroup && (dragState.group || []).length <= 1
            ? insertionConnectionForNode(draggedNode)
            : null;
        const draggedRect = draggedNode ? nodeRect(draggedNode) : null;
        const groupTarget = draggedNode && (draggedNode.images || []).length && (dragState.group || []).length <= 1 && draggedRect
            ? rectOverlapNode(draggedNode.id, draggedRect.x, draggedRect.y, draggedRect.width, draggedRect.height, dragState.groupIds)
            : null;
        // 拖入分组：单个节点、多选（批量拖入）或整个分组（其成员会并入目标分组）都允许并入主分组下的目标分组。
        // 目标分组由主拖动节点的中心命中决定；smartGroupTargetForDraggedNode 已排除正在被拖动的节点/分组。
        const draggedNodes = (dragState.group || []).map(item => nodes.find(n => n.id === item.id)).filter(Boolean);
        const smartGroupTarget = draggedNode ? smartGroupTargetForDraggedNode(draggedNode) : null;
        const imageGroupTarget = draggedNode && (draggedNode.images || []).length && (dragState.group || []).length <= 1
            ? imageGroupTargetForDraggedNode(draggedNode)
            : null;
        if(
            insertHit &&
            insertLoopNodeIntoConnection(draggedNode, insertHit)
        ){
            stateChanged = true;
            render();
        } else if(
            smartGroupTarget &&
            addDraggedNodesToSmartGroup(draggedNodes.length ? draggedNodes : [draggedNode], smartGroupTarget)
        ){
            stateChanged = true;
            render();
        } else if(
            imageGroupTarget &&
            mergeImageNodesIntoGroup(draggedNode.id, imageGroupTarget.id)
        ){
            stateChanged = true;
            render();
        } else if(
            groupTarget &&
            dragState.ctrlGroup &&
            (groupTarget.images || []).length > 1 &&
            mergeImageNodesIntoGroup(draggedNode.id, groupTarget.id)
        ){
            stateChanged = true;
            render();
        } else if(
            draggedNode &&
            autoTarget &&
            dragState.ctrlGroup &&
            (dragState.group || []).length <= 1 &&
            autoConnectDraggedNode(draggedNode, autoTarget)
        ){
            stateChanged = true;
            restoreDraggedNodePosition();
            if(selectedId === draggedNode.id) selectedId = '';
            render();
        } else if(draggedNode && (draggedNode.images || []).length && (dragState.group || []).length <= 1){
            const r = nodeRect(draggedNode);
            const target = rectOverlapNode(draggedNode.id, r.x, r.y, r.width, r.height, dragState.groupIds);
            if(target && isSmartGroupNode(target)){
                if((dragState.group || []).some(item => {
                    const n = nodes.find(x => x.id === item.id);
                    return n && (Math.abs((Number(n.x) || 0) - item.ox) > 1 || Math.abs((Number(n.y) || 0) - item.oy) > 1);
                })) stateChanged = true;
            } else if(target && dragState.ctrlGroup && !isSmartGroupNode(target) && autoConnectDraggedNode(draggedNode, target)){
                stateChanged = true;
                if(!dragState.thumbDetached) restoreDraggedNodePosition();
                if(selectedId === draggedNode.id) selectedId = '';
                render();
            } else if((dragState.group || []).some(item => {
                const n = nodes.find(x => x.id === item.id);
                return n && (Math.abs((Number(n.x) || 0) - item.ox) > 1 || Math.abs((Number(n.y) || 0) - item.oy) > 1);
            })){
                stateChanged = true;
            }
        } else if((dragState.group || []).some(item => {
            const n = nodes.find(x => x.id === item.id);
            return n && (Math.abs((Number(n.x) || 0) - item.ox) > 1 || Math.abs((Number(n.y) || 0) - item.oy) > 1);
        }) || (draggedNode && (Math.abs((draggedNode.x || 0) - dragState.ox) > 1 || Math.abs((draggedNode.y || 0) - dragState.oy) > 1))){
            stateChanged = true;
        }
        if(dragState.thumbDetached) stateChanged = true;
        // 拖出（没落到任何分组上）：普通节点退出所在分组；子分组退出时把它并入过的成员从主分组里撤掉。
        if(draggedNode && !smartGroupTarget && pruneSmartGroupMembershipsForNode(draggedNode)){
            stateChanged = true;
            render();
        }
        if(stateChanged) commitPendingUndo();
        else discardPendingUndo();
        if(stateChanged || dragState.thumbDetached) suppressNodeClickUntil = Date.now() + 180;
        clearDropHighlight();
        loopInsertPreview = null;
        hideAlignGuides();
        dragState = null;
        scheduleSave();
        scheduleConnectionLayerRefresh();
    }
};
window.addEventListener('blur', () => cancelImageReplaceDrag());
shell.addEventListener('wheel', e => {
    if(e.target.closest('.composer,.smart-back,.smart-project-back,.image-edit-modal,.asset-panel,.asset-toggle,.smart-log-toggle,.smart-shortcut-toggle,.smart-workflow-toggle,.smart-agent-panel,.smart-agent-fab,.workflow-transfer-panel,.log-modal,.shortcut-modal,.prompt-node-segments,.prompt-node-text,.prompt-node-llm,.smart-group-list,[data-thumb-scroll]')) return;
    e.preventDefault();
    const rect = shell.getBoundingClientRect();
    const sx = e.clientX - rect.left;
    const sy = e.clientY - rect.top;
    const before = {x:(sx - viewport.x) / viewport.scale, y:(sy - viewport.y) / viewport.scale};
    const factor = Math.exp(-e.deltaY * 0.001);
    viewport.scale = safeScale(viewport.scale * factor);
    viewport.x = sx - before.x * viewport.scale;
    viewport.y = sy - before.y * viewport.scale;
    // 走 rAF 合并：滚轮一秒能来几十上百次事件，每次都同步 applyViewport（全画布重算 +
    // 小地图重建，约 90 次布局读取）会明显掉帧；合并后每帧最多算一次。
    scheduleViewportApply();
    scheduleSave();
}, {passive:false});
shell.ondragover = e => setSmartDropCopyEffect(e, true);
// 2026-10-09（用户反馈：拖入视频节点空白）：拖入瞬间文件还在上传/海报抽帧/可播放转码
// 尚未完成，video 的 playable-video 请求与 poster 的 media-preview 请求会 404/415，
// 此前 img/video 加载失败没有任何重试 → 节点永远空白（数据其实早已就绪）。
// 这里挂全局捕获态 error 委托：命中这两类媒体端点的 img/video 自动递增延迟重载（上限 6 次）。
const SMART_MEDIA_RETRY_STORE = '__smartMediaRetryCount';
const SMART_MEDIA_RETRY_MAX = 6;
document.addEventListener('error', (e) => {
    const el = e.target;
    if(!(el instanceof HTMLImageElement) && !(el instanceof HTMLVideoElement)) return;
    const src = el.getAttribute('src') || '';
    if(!src.includes('/api/media-preview') && !src.includes('/api/playable-video')) return;
    // 2026-10-11（用户反馈：生成的视频黑屏不显示画面）：生成刚完成时海报可能 404/415，
    // Chrome 在 poster 加载失败的暂停态只画纯黑、不画首帧。若视频本体已就绪（readyState>=2），
    // 直接摘掉 poster 并做一次微小 seek 强制绘制当前帧，立即可见，不必等重试。
    if(el instanceof HTMLVideoElement && el.readyState >= 2 && el.hasAttribute('poster')){
        el.removeAttribute('poster');
        try { el.currentTime = Math.min(0.03, (el.duration || 0.1) / 10); } catch {}
    }
    const tries = Number(el[SMART_MEDIA_RETRY_STORE] || 0);
    if(tries >= SMART_MEDIA_RETRY_MAX) {
        // 2026-10-11：重试耗尽（可播副本转码慢于 6 次重试窗口时会发生）→ 退回原始文件直链，
        // 原始 mp4 不依赖转码，一定能播（海报失败由下方 canplay 兜底画帧）。
        if(el instanceof HTMLVideoElement){
            const raw = el.getAttribute('data-url') || el.getAttribute('data-original-src') || '';
            if(raw && !raw.includes('/api/') && el.getAttribute('src') !== raw && !el.dataset.smartRawFallback){
                el.dataset.smartRawFallback = '1';
                el.setAttribute('src', raw);
                try { el.load(); } catch {}
            }
        }
        return;
    }
    el[SMART_MEDIA_RETRY_STORE] = tries + 1;
    setTimeout(() => {
        if(!el.isConnected) return;
        el.src = src;
    }, 1200 * (tries + 1));
}, true);
// 2026-10-11（用户反馈：生成的视频黑屏不显示画面）：poster 加载失败的暂停态视频即使
// canplay 也会黑屏（Chrome 不画首帧）。canplay 时做一次微小 seek 强制绘制当前帧，
// 与海报（本身就是视频抽帧）视觉一致，彻底消除黑屏窗口。
document.addEventListener('canplay', (e) => {
    const v = e.target;
    if(!(v instanceof HTMLVideoElement) || !v.hasAttribute('poster')) return;
    if(!v.paused || v.readyState < 2 || v.dataset.smartPosterPainted) return;
    v.dataset.smartPosterPainted = '1';
    try { v.currentTime = Math.min(0.03, (v.duration || 0.1) / 10); } catch {}
}, true);
shell.ondrop = async e => {
    e.preventDefault();
    if(e.target.closest('.image-node')) return;
    const p = screenToWorld(e);
    const assetRaw = e.dataTransfer.getData('application/x-smart-asset');
    if(assetRaw){
        try {
            const asset = JSON.parse(assetRaw);
            if(asset?.url) {
                pushUndo();
                createImageNodeAt(p, [assetNodeImageFromItem(asset)], {skipUndo:true});
            }
            return;
        } catch {}
    }
    const payload = await resolveSmartImageDropPayload(e.dataTransfer);
    if(payload.type === 'none') return;
    await handleSmartImageDropPayload(payload, '', {point:p, forceNew:true});
};
window.addEventListener('paste', e => {
    // 系统剪贴板里当前有图片文件 → 一定优先贴图（用户最近一次复制的是什么就贴什么）。
    // 之前把“节点剪贴板”放在前面判断，导致 15 分钟内复制过节点后，新复制的图片永远贴不出来（贴的是之前的节点）。
    const files = [...(e.clipboardData?.files || [])].filter(isSupportedUploadFile);
    if(files.length){
        e.preventDefault();
        lastImagePasteAt = Date.now();
        handleFiles(files, selectedId);
        return;
    }
    if(!isEditableTarget(e.target) && shouldPreferNodeClipboardPaste()){
        e.preventDefault();
        if(pasteNodes()) return;
    }
    // 素材库管理页「复制到画布」过来的素材：Ctrl+V 批量粘贴成图片节点
    if(!isEditableTarget(e.target) && pasteAssetsFromInbox()){
        e.preventDefault();
        return;
    }
    if(hasNodeClipboardForPaste() && !isEditableTarget(e.target)){
        e.preventDefault();
        pasteNodes();
    }
});
window.addEventListener('keydown', e => {
    const key = String(e.key || '').toLowerCase();
    if(key === 'escape' && imageReplaceDragState){
        e.preventDefault();
        cancelImageReplaceDrag();
        return;
    }
    if(key === 'r' && !isEditableTarget(e.target)) isRKeyDown = true;
    if(imageEditModal.classList.contains('open') && imageEditMode === 'preview' && !isEditableTarget(e.target)){
        if(e.key === 'ArrowLeft' || e.key === 'ArrowRight'){
            e.preventDefault();
            if(!seekPreviewVideoFrames(e.key === 'ArrowLeft' ? -1 : 1)){
                navigatePreviewImage(e.key === 'ArrowLeft' ? -1 : 1);
            }
            return;
        }
    }
    if(!e.ctrlKey && !e.metaKey && !e.altKey && !isEditableTarget(e.target)){
        if(key === 'z'){
            if(e.repeat) return;
            e.preventDefault();
            toggleZoomPreview();
            return;
        }
        if(key === 'a'){
            if(e.repeat) return;
            e.preventDefault();
            toggleAssetLibrary();
            return;
        }
    }
    // Ctrl+V 不在 keydown 里拦截：keydown 拿不到剪贴板内容，一旦 preventDefault，
    // 原生 paste 事件就不触发，新复制的图片会被当成“粘贴节点”吞掉（贴回之前的图）。
    // 统一交给 window paste 事件按“剪贴板有图先贴图、否则贴节点”的优先级处理。
    if((e.ctrlKey || e.metaKey) && key === 'c' && !isEditableTarget(e.target)){
        const selectionText = window.getSelection?.().toString() || '';
        if(selectionText) return;
        e.preventDefault();
        copySelectedNodes();
        return;
    }
    if(e.key === 'Escape' && imageEditModal.classList.contains('open')){
        closeImageEditor();
        return;
    }
    if((e.ctrlKey || e.metaKey) && key === 'z' && !isEditableTarget(e.target)){
        e.preventDefault();
        performUndo();
        return;
    }
    if((e.key === 'Delete' || e.key === 'Backspace') && (selectedId || selectedIds.length) && !isEditableTarget(e.target)){
        e.preventDefault();
        const ids = selectedIds.length ? selectedIds.slice() : [selectedId];
        pushUndo();
        ids.forEach(id => { undoSuppressed = true; deleteNode(id); undoSuppressed = false; });
        render();
        scheduleSave();
    }
    if((e.ctrlKey || e.metaKey) && e.shiftKey && key === 'g' && !isEditableTarget(e.target)){
        e.preventDefault();
        const ids = selectedIds.length ? selectedIds.slice() : (selectedId ? [selectedId] : []);
        const ok = ids.map(id => ungroupNode(id)).some(Boolean);
        if(ok) return;
    }
    if((e.ctrlKey || e.metaKey) && key === 'g' && !e.shiftKey && !isEditableTarget(e.target)){
        e.preventDefault();
        groupSelectedNodes();
    }
});
