engineSelect.onchange = () => {
    const node = activeComposerNode() || activeSettingsSubject() || selectedNode();
    const panelKind = smartPanelKindForNode(node) || activeSmartPanelKind || smartPanelKindForSettings(settings);
    const allowedEngines = smartPanelEngineOptions(panelKind);
    const nextEngine = allowedEngines.includes(engineSelect.value) ? engineSelect.value : (allowedEngines[0] || 'api');
    if(engineSelect.value !== nextEngine) engineSelect.value = nextEngine;
    settings.engine = nextEngine;
    applyRecentSmartSettingsForCurrentMode();
    settings.engine = nextEngine;
    if(settings.engine === 'comfy') settings.apiKind = 'image';
    if(settings.engine === 'h3'){
        settings.apiKind = 'video';
        settings.comfyMode = 'custom';
        settings.comfyWorkflow = H3_COMFY_WORKFLOW;
        if(!settings.comfyParams) settings.comfyParams = minimaxH3DefaultRunSettings().comfyParams;
    }
    applySmartPanelKindLock(panelKind, settings);
    syncApiKindToggleVisibility();
    syncImageOutputModeToggle();
    renderDynamicParams();
    persistActiveSmartSettings();
    syncComposerFixedEngine(activeComposerNode() || selectedNode());
    render();
    scheduleSave();
};
function syncApiKindToggleVisibility(){
    if(!apiKindToggle) return;
    const node = activeComposerNode() || activeSettingsSubject() || selectedNode();
    const panelKind = smartPanelKindForNode(node) || activeSmartPanelKind || smartPanelKindForSettings(settings);
    applySmartPanelKindLock(panelKind, settings);
    const locked = smartPanelApiKindLocked(panelKind);
    apiKindToggle.style.display = !locked && isApiLikeEngine(settings.engine) ? 'inline-flex' : 'none';
    apiKindToggle.querySelectorAll('[data-kind]').forEach(btn => btn.classList.toggle('active', btn.dataset.kind === (settings.apiKind || 'image')));
}
if(apiKindToggle){
    apiKindToggle.querySelectorAll('[data-kind]').forEach(btn => {
        btn.onclick = e => {
            e.preventDefault();
            e.stopPropagation();
            const node = activeComposerNode() || activeSettingsSubject() || selectedNode();
            const panelKind = smartPanelKindForNode(node) || activeSmartPanelKind || smartPanelKindForSettings(settings);
            if(smartPanelApiKindLocked(panelKind)){
                applySmartPanelKindLock(panelKind, settings);
                syncApiKindToggleVisibility();
                persistActiveSmartSettings();
                return;
            }
            const kind = btn.dataset.kind;
            if(kind === settings.apiKind) return;
            settings.apiKind = kind;
            applyRecentSmartSettingsForCurrentMode();
            syncApiKindToggleVisibility();
            syncImageOutputModeToggle();
            renderDynamicParams();
            persistActiveSmartSettings();
            scheduleSave();
        };
    });
}
