fileInput.onchange = () => {
    const groupPoint = pendingGroupUploadPoint;
    if(!fileInput.files?.length){
        pendingGroupUploadPoint = null;
        uploadTargetId = '';
        uploadReplaceIndex = -1;
        fileInput.multiple = true;
        return;
    }
    const targetId = groupPoint ? '' : (uploadTargetId || selectedId);
    const replaceIndex = Number(uploadReplaceIndex);
    const uploadOptions = groupPoint
        ? {point:groupPoint}
        : (Number.isInteger(replaceIndex) && replaceIndex >= 0 ? {replaceIndex} : {});
    handleFiles(fileInput.files, targetId, uploadOptions);
    pendingGroupUploadPoint = null;
    uploadTargetId = '';
    uploadReplaceIndex = -1;
    fileInput.value = '';
    fileInput.multiple = true;
};
