smartAgentMessages?.addEventListener('click', async event => {
    const btn = event.target.closest('[data-agent-copy-message]');
    const outputBtn = event.target.closest('[data-agent-output-url]');
    if(outputBtn){
        event.preventDefault();
        event.stopPropagation();
        const url = outputBtn.dataset.agentOutputUrl || '';
        let found = null;
        for(const node of nodes || []){
            const index = (node.images || []).findIndex(img => img?.url === url);
            if(index >= 0){ found = {node, index}; break; }
        }
        if(found) openImagePreview(found.node.id, found.index);
        else smartLogPreviewNode(url, 'image');
        return;
    }
    if(!btn) return;
    event.preventDefault();
    event.stopPropagation();
    const msg = smartAgentMessagesState[Number(btn.dataset.agentCopyMessage)];
    const ok = await copyTextToClipboard(msg?.content || '');
    const label = btn.querySelector('span');
    const oldText = label?.textContent || '复制';
    btn.classList.toggle('copied', ok);
    if(label) label.textContent = ok ? '已复制' : '失败';
    setTimeout(() => {
        btn.classList.remove('copied');
        if(label) label.textContent = oldText;
    }, 1400);
});
