async function handleSmartPromptPasteFiles(files){
    const fileList = [...(files || [])].filter(isSupportedUploadFile);
    if(!fileList.length) return;
    try {
        const uploaded = await uploadFiles(fileList);
        const images = (uploaded || []).filter(file => file?.url);
        if(!images.length) return;
        appendImagesToSmartNode(images, selectedId, {});
    } catch(err) {
        toast(err.message || tr('smart.toastUploadFail'));
    }
}
function bindSmartPromptPaste(el){
    if(!el) return;
    el.addEventListener('paste', event => {
        const files = [...(event.clipboardData?.files || [])].filter(isSupportedUploadFile);
        if(!files.length) return;
        event.preventDefault();
        event.stopPropagation();
        handleSmartPromptPasteFiles(files);
    });
}
