document.getElementById('promptLlmTranslate')?.addEventListener('click', async event => {
    event.preventDefault();
    event.stopPropagation();
    const node = activePromptLlmComposerNode();
    if(!node) return;
    const text = String(promptLlmInstruction?.value || node.llmInstruction || '').trim();
    if(!text){ toast('没有可翻译的内容'); return; }
    ensurePromptNodeLlmDefaults(node);
    const btn = event.currentTarget;
    btn.disabled = true; btn.style.opacity = '0.5';
    try {
        const provider = resolveChatProviderId(node.llmProvider || '');
        const model = resolveChatModel(node.llmModel || '', provider);
        const result = await fetch('/api/llm/canvas', {
            method:'POST',
            headers:{'Content-Type':'application/json'},
            body:JSON.stringify({
                message:'请将下面的文本进行英汉互译：如果原文主要是中文，请翻译成自然、简洁、准确的英文；如果原文主要是英文，请翻译成自然、准确的中文。保留换行、数字、括号、专有名词和技术术语，只输出译文，不要解释。\n\n' + text,
                messages:[], images:[], videos:[], files:[],
                model, provider,
                ms_model: provider === 'modelscope' ? model : '',
                system_prompt:'You are a professional translator. Translate between Chinese and English only. Keep meaning, structure, line breaks, numbers, punctuation, brand names, technical terms. Output translation only.'
            })
        }).then(async r => { if(!r.ok) throw new Error(await r.text()); return r.json(); });
        const translated = (result.text || '').trim();
        if(!translated){ toast('翻译结果为空'); return; }
        node.llmInstruction = translated;
        if(promptLlmInstruction) promptLlmInstruction.value = translated;
        scheduleSave();
        toast('已翻译');
    } catch(e) { toast((e.message || '翻译失败').slice(0, 160)); }
    finally { btn.disabled = false; btn.style.opacity = ''; }
});
