let billingData = { providers: [], rate: 100, logs: [] };
async function loadBillingData(){
    try {
        const r = await fetch('/api/billing/status');
        billingData = await r.json();
        renderBillingPanel();
    } catch(e){}
}
function toggleBillingPanel(){
    const m = document.getElementById('billingModal');
    if(m.classList.contains('open')){
        m.classList.remove('open');
    } else {
        m.classList.add('open');
        loadBillingData();
        const btn = document.getElementById('billingToggle');
        if(btn){
            const width = Math.min(640, window.innerWidth - 28);
            const r = btn.getBoundingClientRect();
            let left = r.left + r.width/2 - width/2;
            left = Math.max(14, Math.min(left, window.innerWidth - width - 14));
            const top = r.bottom + 10;
            m.style.setProperty('left', Math.round(left)+'px', 'important');
            m.style.setProperty('right', 'auto', 'important');
            m.style.setProperty('top', Math.round(top)+'px', 'important');
            m.style.setProperty('width', width+'px', 'important');
            m.style.setProperty('max-width', width+'px', 'important');
        }
    }
}
function closeBillingPanel(){
    document.getElementById('billingModal').classList.remove('open');
}
function renderBillingPanel(){
    const d = billingData;
    document.getElementById('billingRate').textContent = d.rate || 100;
    const totalBal = (d.providers||[]).reduce((s,p)=>s+(p.balance||0),0);
    const totalUsed = (d.providers||[]).reduce((s,p)=>s+(p.total_used||0),0);
    document.getElementById('billingTotalBal').textContent = '¥' + totalBal.toFixed(2);
    document.getElementById('billingTotalUsed').textContent = '¥' + totalUsed.toFixed(2);
    const pl = document.getElementById('billingProviderList');
    if(!(d.providers||[]).length){
        pl.innerHTML = '<div style="color:#64748b;font-size:12px;padding:8px 0">暂无平台余额数据。请在 API 设置中为每个平台设置余额。</div>';
    } else {
        pl.innerHTML = d.providers.map(p => `
            <div style="display:flex;justify-content:space-between;align-items:center;padding:10px 12px;background:rgba(255,255,255,.04);border-radius:8px">
                <div>
                    <div style="font-weight:600;font-size:13px">${p.name}</div>
                    <div style="font-size:11px;color:#94a3b8">已用 ¥${(p.total_used||0).toFixed(2)} · ${p.total_count||0}次</div>
                </div>
                <div style="font-weight:700;font-size:16px;color:${(p.balance||0)>0?'#22c55e':'#ef4444'}">¥${(p.balance||0).toFixed(2)}</div>
            </div>
        `).join('');
    }
    const ll = document.getElementById('billingLogList');
    const logs = (d.logs||[]).slice(-10).reverse();
    if(!logs.length){
        ll.innerHTML = '<div style="color:#64748b;font-size:12px;padding:4px 0">暂无消耗记录</div>';
    } else {
        ll.innerHTML = logs.map(l => `
            <div style="display:flex;justify-content:space-between;padding:4px 0;border-bottom:1px solid rgba(255,255,255,.05)">
                <span style="color:#94a3b8">${l.time}</span>
                <span style="color:#e2e8f0">${l.model}</span>
                <span style="color:#ef4444">-¥${(l.cost||0).toFixed(2)}</span>
            </div>
        `).join('');
    }
    // 消费趋势（近14天）+ 模型消耗排行
    renderBillingTrend(d.logs||[]);
    renderBillingModelTable(d.logs||[]);
    if(window.lucide) window.lucide.createIcons();
}
function renderBillingTrend(logs){
    const el = document.getElementById('billingTrend');
    if(!el) return;
    const days = 14;
    const now = new Date();
    const buckets = {};
    const labels = [];
    for(let i=days-1;i>=0;i--){
        const dt = new Date(now); dt.setDate(now.getDate()-i);
        const key = dt.toISOString().slice(0,10);
        buckets[key] = 0; labels.push(key);
    }
    logs.forEach(l => {
        if(l.type !== 'deduct') return;
        const key = String(l.time||'').slice(0,10);
        if(key in buckets) buckets[key] += (l.cost||0);
    });
    const vals = labels.map(k => buckets[k]);
    const max = Math.max(...vals, 0.0001);
    const W = 560, H = 130, pad = 26, bw = (W - pad*2) / days;
    let bars = '';
    labels.forEach((k,i) => {
        const v = vals[i];
        const h = Math.max(v>0?3:0, (v/max)*(H-pad*2));
        const x = pad + i*bw + bw*0.18;
        const y = H - pad - h;
        const mmdd = k.slice(5).replace('-','/');
        const color = v>0 ? '#10b981' : 'rgba(255,255,255,.08)';
        bars += `<rect x="${x.toFixed(1)}" y="${y.toFixed(1)}" width="${(bw*0.64).toFixed(1)}" height="${h.toFixed(1)}" rx="2" fill="${color}"><title>${k}: ¥${v.toFixed(2)}</title></rect>`;
        if(i%2===0) bars += `<text x="${(x+bw*0.32).toFixed(1)}" y="${H-8}" font-size="8" fill="#64748b" text-anchor="middle">${mmdd}</text>`;
    });
    const total = vals.reduce((a,b)=>a+b,0);
    el.innerHTML = `
        <div style="display:flex;justify-content:space-between;align-items:baseline;margin-bottom:6px">
            <span style="font-size:11px;color:#94a3b8">14天累计</span>
            <span style="font-size:15px;font-weight:800;color:#34d399">¥${total.toFixed(2)}</span>
        </div>
        <svg viewBox="0 0 ${W} ${H}" style="width:100%;height:auto;display:block">
            <line x1="${pad}" y1="${H-pad}" x2="${W-pad}" y2="${H-pad}" stroke="rgba(255,255,255,.1)" stroke-width="1"/>
            ${bars}
        </svg>`;
}
function renderBillingModelTable(logs){
    const el = document.getElementById('billingModelTable');
    if(!el) return;
    const agg = {};
    logs.forEach(l => {
        if(l.type !== 'deduct') return;
        const key = (l.provider||'?') + '||' + (l.model||'未知模型');
        if(!agg[key]) agg[key] = {provider:l.provider||'?', model:l.model||'未知模型', count:0, cost:0};
        agg[key].count += 1;
        agg[key].cost += (l.cost||0);
    });
    const rows = Object.values(agg).sort((a,b)=>b.cost-a.cost);
    if(!rows.length){
        el.innerHTML = '<div style="color:#64748b;font-size:12px;padding:8px 0">暂无消耗数据</div>';
        return;
    }
    el.innerHTML = `
        <table style="width:100%;border-collapse:collapse;font-size:12px">
            <thead>
                <tr style="color:#64748b;text-align:left">
                    <th style="padding:6px 8px;font-weight:600">平台 / 模型</th>
                    <th style="padding:6px 8px;font-weight:600;text-align:center">次数</th>
                    <th style="padding:6px 8px;font-weight:600;text-align:right">消耗(元)</th>
                </tr>
            </thead>
            <tbody>
                ${rows.map(r => `
                    <tr style="border-top:1px solid rgba(255,255,255,.05)">
                        <td style="padding:7px 8px">
                            <div style="color:#e2e8f0;font-weight:600;max-width:300px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${r.model}</div>
                            <div style="font-size:10px;color:#64748b">${r.provider}</div>
                        </td>
                        <td style="padding:7px 8px;text-align:center;color:#94a3b8">${r.count}</td>
                        <td style="padding:7px 8px;text-align:right;color:#ef4444;font-weight:700">¥${r.cost.toFixed(2)}</td>
                    </tr>`).join('')}
            </tbody>
        </table>`;
}
// 每30秒刷新导航栏余额
setInterval(loadBillingData, 30000);
loadBillingData();
